 const draw=()=>{let body='';if(step===0)body=`<div class="form-grid"><div class="field"><label>Product ID</label><input value="${esc(draft.id)}" disabled></div><div class="field"><label>Product/device family</label><input id="pmFamily" value="${esc(draft.family)}"></div><div class="field"><label>Part number</label><input id="pmPart" value="${esc(draft.partNumber)}"></div><div class="field"><label>Product revision</label><input id="pmRev" value="${esc(draft.revision)}"></div><div class="field"><label>Hardware revision</label><input id="pmHw" value="${esc(draft.hw||'')}"></div><div class="field"><label>Software revision</label><input id="pmSw" value="${esc(draft.sw||'')}"></div><div class="field full"><label><input id="pmSafety" type="checkbox" style="width:auto;min-height:auto" ${draft.safety?'checked':''}> Product-safety relevant by default</label></div></div>`;else if(step===1)body=`<div class="callout"><h3>Exact material definition</h3><p>Component lines generate controlled material requirements. Consumable lines stay optional and can carry unit cost/waste for build costing.</p></div><div class="product-bom-editor" style="margin-top:12px"><div class="product-bom-edit-head"><span>Type</span><span>Part</span><span>Description</span><span>Rev</span><span>Qty/unit</span><span>Unit</span><span>€/unit</span><span>Waste %</span><span></span></div>${bomRows()}</div><div style="margin-top:10px">${btn('+ Add BOM item','data-add-bom','button secondary')}</div>`;else if(step===2)body=`<div class="callout"><h3>Default route proposal</h3><p>New requests inherit this released-process sequence as a <strong>proposal</strong>. Process Engineering must still assess and confirm the actual route before timing is committed.</p></div><div class="product-route-editor" style="margin-top:12px">${routeRows()}</div><div style="margin-top:10px">${btn('+ Add process step','data-add-route','button secondary')}</div>`;else body=`<div class="grid cols-2"><div class="card"><span class="subtle">Product</span><h3>${esc(draft.family||'—')}</h3><p>${esc(draft.partNumber||'—')} · Rev ${esc(draft.revision||'—')} · ${draft.safety?'Product safety relevant':'Standard'}</p></div><div class="card"><span class="subtle">Controlled definition</span><h3>${draft.bom.length} BOM items · ${draft.defaultRoute.length} route steps</h3><p>Existing requests retain their captured configuration. This master becomes the basis for new requests.</p></div></div><div class="route-sequence" style="margin-top:12px">${draft.defaultRoute.map((id,i)=>`<span>${i+1}. ${esc(App.state.processes.find(p=>p.id===id)?.name||id)}</span>`).join('')}</div>`;
  openModal(`${existing?'Edit':'New'} product · ${steps[step]}`,`<div class="wizard-shell"><div class="wizard-progress">${steps.map((_,i)=>`<div class="wizard-step ${i<step?'done':''} ${i===step?'active':''}"></div>`).join('')}</div>${body}</div>`,`${step?btn('Back','data-pm-back','button'):btn('Cancel','data-modal-close','button')}${step<steps.length-1?btn('Next →','data-pm-next','button primary'):btn(existing?'Save controlled update':'Create product','data-pm-save','button primary')}`,true);
  setTimeout(()=>{const next=$('[data-pm-next]'),back=$('[data-pm-back]'),save=$('[data-pm-save]');if(next)next.onclick=()=>{collect();if(step===0&&(!draft.family||!draft.partNumber||!draft.revision)){toast('Product family, part number and revision are required.',true);return}if(step===1&&!draft.bom.length){toast('Define at least one controlled BOM item.',true);return}if(step===2&&!draft.defaultRoute.length){toast('Define at least one released process in the default route.',true);return}step++;draw()};if(back)back.onclick=()=>{collect();step--;draw()};if(save)save.onclick=async()=>{const duplicate=App.state.products.find(p=>p.id!==draft.id&&p.partNumber===draft.partNumber&&p.revision===draft.revision);if(duplicate){toast(`Part ${draft.partNumber} Rev ${draft.revision} already exists as ${duplicate.id}.`,true);return}draft.revisionHistory=draft.revisionHistory||[];if(existing&&original.revision!==draft.revision)draft.revisionHistory.push({revision:original.revision,replacedAt:P.now(),reason:'Product master updated'});if(existing)Object.assign(existing,draft);else App.state.products.push(draft);P.ensureMaterialModel(App.state);P.audit(App.state,existing?'Product master updated':'Product master created','Product',draft.id,existing?`${original.partNumber} Rev ${original.revision}`:'—',`${draft.partNumber} Rev ${draft.revision}`,`${draft.bom.length} BOM items; ${draft.defaultRoute.length} default route steps`);await persist();closeModal();render();toast(`${draft.family} product master saved.`)};$$('[data-remove-bom]').forEach(el=>el.onclick=()=>{collect();draft.bom.splice(Number(el.dataset.removeBom),1);draw()});const addBom=$('[data-add-bom]');if(addBom)addBom.onclick=()=>{collect();draft.bom.push({id:P.uid('BOM'),kind:'component',partNumber:'',description:'',revision:'A',qtyPerUnit:1,unit:'pcs',unitCost:0,wastePct:0,basis:'unit'});draw()};$$('[data-route-up]').forEach(el=>el.onclick=()=>{collect();const i=Number(el.dataset.routeUp);[draft.defaultRoute[i-1],draft.defaultRoute[i]]=[draft.defaultRoute[i],draft.defaultRoute[i-1]];draw()});$$('[data-route-down]').forEach(el=>el.onclick=()=>{collect();const i=Number(el.dataset.routeDown);[draft.defaultRoute[i+1],draft.defaultRoute[i]]=[draft.defaultRoute[i],draft.defaultRoute[i+1]];draw()});$$('[data-route-remove]').forEach(el=>el.onclick=()=>{collect();draft.defaultRoute.splice(Number(el.dataset.routeRemove),1);draw()});const addRoute=$('[data-add-route]');if(addRoute)addRoute.onclick=()=>{collect();const id=App.state.processes.find(p=>p.status==='Released'&&!draft.defaultRoute.includes(p.id))?.id||App.state.processes.find(p=>p.status==='Released')?.id;if(!id){toast('No released process exists to add.',true);return}draft.defaultRoute.push(id);draw()};},0);
 };
 draw();
