function pct(n,d){return d>0?Math.max(0,100*Number(n||0)/d):0}
function capacityState(forward){const eq=Object.values(forward.equipment||{}),sk=Object.values(forward.skills||{}),eqCap=eq.reduce((n,s)=>n+Number(s.capacity||0),0),skCap=sk.reduce((n,s)=>n+Number(s.capacity||0),0),eqNow=eq.reduce((n,s)=>n+Number(s.committed?.[0]||0),0),skNow=sk.reduce((n,s)=>n+Number(s.committed?.[0]||0),0),eqPeak=Math.max(0,...eq.flatMap(s=>(s.committed||[]).map((v,i)=>pct(Number(v||0)+Number(s.pipeline?.[i]||0),Number(s.capacity||0))))),skPeak=Math.max(0,...sk.flatMap(s=>(s.committed||[]).map((v,i)=>pct(Number(v||0)+Number(s.pipeline?.[i]||0),Number(s.capacity||0)))));return {eqCap,skCap,eqNow,skNow,eqAvail:Math.max(0,eqCap-eqNow),skAvail:Math.max(0,skCap-skNow),eqUtil:pct(eqNow,eqCap),skUtil:pct(skNow,skCap),eqPeak,skPeak};}
function capacityMetric(label,demand,capacity,unit='h/wk'){const u=pct(demand,capacity);return `<div class="card metric capacity-metric"><div class="label">${esc(label)}</div><div class="value">${u.toFixed(0)}%</div><div class="capacity-track"><span style="width:${Math.min(100,u).toFixed(1)}%"></span></div><div class="trend ${u>100?'bad':u>85?'warn':'good'}">${Number(demand).toFixed(1)} / ${Number(capacity).toFixed(1)} ${esc(unit)} · ${Math.max(0,Number(capacity)-Number(demand)).toFixed(1)} available</div></div>`}
function capacityLoadTable(seriesMap,index=0,includePipeline=false){const rows=Object.values(seriesMap||{}).map(s=>{const committed=Number(s.committed?.[index]||0),pipeline=includePipeline?Number(s.pipeline?.[index]||0):0,demand=committed+pipeline,cap=Number(s.capacity||0),util=pct(demand,cap);return {label:s.label,demand,cap,util}}).sort((a,b)=>b.util-a.util);return `<div class="table-wrap"><table class="data-table capacity-table"><thead><tr><th>Resource</th><th>Demand</th><th>Current available capacity</th><th>Utilization</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.label)}</strong></td><td>${r.demand.toFixed(1)} h/wk</td><td>${r.cap.toFixed(1)} h/wk</td><td><strong class="${r.util>100?'bad-text':r.util>85?'warn-text':'good-text'}">${r.util.toFixed(0)}%</strong><div class="capacity-track small"><span style="width:${Math.min(100,r.util).toFixed(1)}%"></span></div></td></tr>`).join('')||'<tr><td colspan="4">No resource master data.</td></tr>'}</tbody></table></div>`}
