 `<div class="card"><div class="section-title-row"><div><span class="eyebrow">LAB STAFF</span><h2>People, availability & certified skills</h2><div class="subtle">Staff records define the people AUTO-PLAN may assign. Skills remain certificate-gated and cannot be granted by editing a person.</div></div>${canSkills?btn('+ Add staff','data-add-staff','button primary'):''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Person</th><th>Role / team</th><th>Availability</th><th>Valid certified skills</th><th>Actions</th></tr></thead><tbody>${App.state.staff.map(st=>{const valid=(App.state.trainingCertificates||[]).filter(c=>c.staffId===st.id&&c.status==='Valid'&&(!c.expiresAt||c.expiresAt>=P.todayISO()));return `<tr><td><strong>${esc(st.name)}</strong><br><small>${esc(st.employeeNo||st.id)}</small></td><td>${esc(roleLabel(st.role))}<br><small>${esc(st.team||'Prototype Lab')}</small></td><td>${status(st.available?'Available':'Unavailable')}</td><td>${valid.map(c=>`<span class="pill">${esc(App.state.competencies.find(x=>x.id===c.skillId)?.name||c.skillId)}</span>`).join(' ')||'—'}</td><td><div class="route-toolbar">${canSkills?btn('Edit person',`data-edit-staff="${st.id}"`,'button tiny secondary'):''}${canSkills?btn('Manage competencies',`data-edit-staff-skills="${st.id}"`,'button tiny secondary'):''}</div></td></tr>`}).join('')}</tbody></table></div></div>`+
 `<div class="card"><div class="section-title-row"><div><span class="eyebrow">FINANCE & COSTING</span><h2>Cost master data</h2><div class="subtle">AUTO-PLAN bookings + these rates produce request estimates; actual material, labour, equipment and rework create variance KPIs.</div></div>${can('finance:manage')||currentRole()==='administrator'?btn('Edit finance rates','data-edit-finance','button primary'):''}</div><div class="grid cols-3">${metric('Contingency',`${Number(finance.contingencyPct||0)}%`)+metric('Equipment rates',`${App.state.equipment.length} defined`)+metric('Costed standards',`${App.state.processes.length+(App.state.standardTests||[]).length}`)}</div><div style="height:12px"></div><div class="grid cols-2"><div><h3>Labour rates</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Labour role</th><th>Internal rate</th></tr></thead><tbody>${roleRates}</tbody></table></div></div><div><h3>Material standard costs</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Part / revision</th><th>Material</th><th>€/unit</th><th></th></tr></thead><tbody>${App.state.materials.slice(0,12).map(m=>`<tr><td>${esc(m.partNumber)} Rev ${esc(m.revision)}</td><td>${esc(m.description)}</td><td>${P.currency(m.unitCost||0)}</td><td>${can('finance:manage')||currentRole()==='administrator'?btn('Edit',`data-edit-material-cost="${m.id}"`,'button tiny secondary'):''}</td></tr>`).join('')}</tbody></table></div></div></div><div class="callout" style="margin-top:12px"><strong>Cost formula</strong><br>planned labour + equipment hours + exact BOM material cost + standard process/test charges + development/external services + contingency. Closed builds retain actual cost and cost-of-poor-quality for KPI learning.</div></div>`;
