function bindDragDrop(){let dragged=null;$$('.process-card[draggable="true"]').forEach(card=>{card.ondragstart=e=>{dragged=card;card.classList.add('dragging');e.dataTransfer.effectAllowed='move'};card.ondragend=()=>card.classList.remove('dragging');card.ondragover=e=>e.preventDefault();card.ondrop=async e=>{e.preventDefault();if(!dragged||dragged===card)return;const route=App.state.routes.find(r=>r.requestId===App.workspaceId);const from=Number(dragged.dataset.stepIndex),to=Number(card.dataset.stepIndex);const [moved]=route.steps.splice(from,1);route.steps.splice(to,0,moved);route.steps.forEach((s,i)=>s.order=i+1);P.audit(App.state,'Process route reordered','Request',App.workspaceId,from+1,to+1,`Moved ${moved.name}`);await persist();render();toast('Process route reordered and audit history updated.')}})}
function planBookingKey(b){return `${b.requestId||''}|${b.stepId||b.itemKey||b.id||''}|${b.taskType||b.type||''}`}
function planProposalChanges(before,after,requestIds){
 const ids=new Set(requestIds||[]),oldMap=new Map((before.bookings||[]).filter(b=>!ids.size||ids.has(b.requestId)).map(b=>[planBookingKey(b),b])),newMap=new Map((after.bookings||[]).filter(b=>!ids.size||ids.has(b.requestId)).map(b=>[planBookingKey(b),b])),rows=[];
 const desc=(s,b)=>{if(!b)return '—';const eq=s.equipment?.find(x=>x.id===b.equipmentId)?.name||'—',st=s.staff?.find(x=>x.id===b.staffId)?.name||'—';return `${P.formatDateTime(b.start)} · ${eq} · ${st}`};
 for(const key of new Set([...oldMap.keys(),...newMap.keys()])){const a=oldMap.get(key),b=newMap.get(key);if(!a&&b)rows.push({requestId:b.requestId,task:b.stepName||b.description||b.stepId,type:'Added',before:'—',after:desc(after,b)});else if(a&&!b)rows.push({requestId:a.requestId,task:a.stepName||a.description||a.stepId,type:'Removed',before:desc(before,a),after:'—'});else if(a&&b&&(a.start!==b.start||a.equipmentId!==b.equipmentId||a.staffId!==b.staffId||Number(a.durationHours)!==Number(b.durationHours)))rows.push({requestId:b.requestId,task:b.stepName||b.description||b.stepId,type:'Changed',before:desc(before,a),after:desc(after,b)});}
 return rows;
}
function showPlanProposal({mode,proposedState,requestIds,results=[],contextEvent=null}){
 const before=App.state,ids=requestIds||[],changes=planProposalChanges(before,proposedState,ids),forecasts=ids.map(id=>{const a=before.requests.find(r=>r.id===id),b=proposedState.requests.find(r=>r.id===id);return {id,title:a?.title||id,before:a?.forecastDate||null,after:b?.forecastDate||null,commit:a?.currentCommitmentDate||null,quality:b?.triage?.planQuality||'Not planned'}}).filter(x=>x.before!==x.after||mode==='single'),blocked=results.filter(x=>x.ok===false);
 App.pendingPlanProposal={mode,proposedState,requestIds:ids,contextEvent};
 const title=mode==='portfolio'?'Portfolio optimization proposal':'AUTO-PLAN proposal';
 openModal(title,`<div class="callout ${blocked.length?'warn':''}"><h3>Review before applying</h3><p>No live booking or committed delivery date has been changed yet. Review the forecast and resource movements below, then explicitly Accept or Reject the proposal.${contextEvent?` This proposal incorporates <strong>${esc(planningSituationLabel(contextEvent))}</strong>.`:''}</p></div>
 <div class="grid cols-4" style="margin-top:12px"><div class="mini-kpi"><span>Builds assessed</span><strong>${ids.length}</strong></div><div class="mini-kpi"><span>Forecast changes</span><strong>${forecasts.filter(x=>x.before!==x.after).length}</strong></div><div class="mini-kpi"><span>Booking changes</span><strong>${changes.length}</strong></div><div class="mini-kpi"><span>Structural gaps</span><strong>${blocked.length}</strong></div></div>
 <section class="report-section"><h3>Delivery forecast impact</h3>${forecasts.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Build</th><th>Current forecast</th><th>Proposed forecast</th><th>Current commitment</th><th>Plan quality</th></tr></thead><tbody>${forecasts.map(x=>`<tr><td><strong>${esc(x.id)}</strong><br><small>${esc(x.title)}</small></td><td>${P.formatDate(x.before)}</td><td>${P.formatDate(x.after)}</td><td>${P.formatDate(x.commit)}${x.commit&&x.after&&x.commit!==x.after?'<br><small class="warn-text">Replan decision required after acceptance</small>':''}</td><td>${esc(x.quality)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty compact">No forecast dates change.</div>'}</section>
 <section class="report-section"><h3>Resource / timing changes</h3>${changes.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Build</th><th>Task</th><th>Change</th><th>Current</th><th>Proposed</th></tr></thead><tbody>${changes.slice(0,100).map(x=>`<tr><td>${esc(x.requestId||'—')}</td><td>${esc(x.task)}</td><td>${esc(x.type)}</td><td>${esc(x.before)}</td><td>${esc(x.after)}</td></tr>`).join('')}</tbody></table></div>${changes.length>100?`<small>Showing first 100 of ${changes.length} changed bookings.</small>`:''}`:'<div class="empty compact">No booking assignment or timing changes.</div>'}</section>
 ${blocked.length?`<section class="report-section"><h3>Capability gaps</h3>${blocked.map(x=>`<div class="callout bad"><strong>${esc(x.requestId)}</strong><p>${esc(x.error)}</p></div>`).join('')}</section>`:''}
 <div class="field"><label>Planning decision note <small>optional but retained in audit history</small></label><textarea id="planProposalNote" placeholder="Why are you accepting or rejecting this plan?"></textarea></div>`,
 `${btn('Reject proposal','data-reject-plan-proposal','button danger')}${btn('Accept proposal','data-accept-plan-proposal','button primary')}`,true);
 setTimeout(()=>{const ac=$('[data-accept-plan-proposal]'),rj=$('[data-reject-plan-proposal]');if(ac)ac.onclick=acceptPlanProposal;if(rj)rj.onclick=rejectPlanProposal},0)
}
async function acceptPlanProposal(){const pp=App.pendingPlanProposal;if(!pp)return;const note=$('#planProposalNote')?.value.trim()||'Accepted after reviewing forecast and resource changes.',currentIdentity=P.deepClone(App.state.identity);App.state=P.deepClone(pp.proposedState);App.state.identity=currentIdentity;App.identity=new P.DemoIdentityProvider(App.state);populateRoles();App.state.settings=App.state.settings||{};App.state.settings.planningNeedsReview=false;P.audit(App.state,pp.mode==='portfolio'?'Portfolio plan proposal accepted':'AUTO-PLAN proposal accepted','Planning',pp.mode==='portfolio'?'PORTFOLIO':pp.requestIds[0],'Proposed','Applied',note);App.pendingPlanProposal=null;await persist();closeModal();render();toast('Planning proposal accepted and applied. Committed dates remain unchanged until any required replan is separately approved.')}
async function rejectPlanProposal(){const pp=App.pendingPlanProposal;if(!pp)return;const note=$('#planProposalNote')?.value.trim()||'Proposal rejected; live plan retained.';P.audit(App.state,pp.mode==='portfolio'?'Portfolio plan proposal rejected':'AUTO-PLAN proposal rejected','Planning',pp.mode==='portfolio'?'PORTFOLIO':pp.requestIds[0],'Proposed','Rejected',note);App.pendingPlanProposal=null;await persist();closeModal();render();toast('Planning proposal rejected. Existing bookings and forecasts were retained.')}
async function autoPlan(id,contextEvent=null){const proposed=P.deepClone(App.state);try{const changes=new P.PlannerService().autoPlan(proposed,id),r=proposed.requests.find(x=>x.id===id),live=requestById(id);if(live?.currentCommitmentDate&&r?.forecastDate&&live.currentCommitmentDate!==r.forecastDate)r.pendingReplanContext=contextEvent?{eventId:contextEvent.id,reasonCategory:planningSituationReasonCategory(contextEvent),reason:`${contextEvent.type}: ${contextEvent.reason}`,eventAction:'planning proposal',createdAt:P.now()}:live.pendingReplanContext;showPlanProposal({mode:'single',proposedState:proposed,requestIds:[id],results:[{requestId:id,ok:true,bookings:changes.length,forecast:r.forecastDate,quality:r.triage?.planQuality}],contextEvent});}catch(e){if(['ZERO_EQUIPMENT_CAPABILITY','ZERO_REQUIRED_SKILL'].includes(e.code)){toast(e.message,true);return}console.error('AUTO-PLAN preview failed',e);toast(`AUTO-PLAN proposal could not be created: ${e.message}`,true)}}
async function optimizePortfolio(opts={}){const contextEvent=opts?.contextEvent||null,includePotential=App.filters.planPotential!==false,proposed=P.deepClone(App.state),results=new P.PlannerService().autoPlanPortfolio(proposed,{includePotential}),ids=proposed.requests.filter(r=>!['DELIVERED','CLOSED','RELEASED'].includes(r.status)).map(r=>r.id);for(const id of ids){const live=App.state.requests.find(r=>r.id===id),next=proposed.requests.find(r=>r.id===id);if(live?.currentCommitmentDate&&next?.forecastDate&&live.currentCommitmentDate!==next.forecastDate)next.pendingReplanContext=contextEvent?{eventId:contextEvent.id,reasonCategory:planningSituationReasonCategory(contextEvent),reason:`${contextEvent.type}: ${contextEvent.reason}`,eventAction:'portfolio proposal',createdAt:P.now()}:live.pendingReplanContext;}showPlanProposal({mode:'portfolio',proposedState:proposed,requestIds:ids,results,contextEvent})}
async function commitTriage(id){const r=requestById(id),mat=P.materialPlanningAssessment(App.state,r),proc=P.processPlanningAssessment(App.state,r);if(!can('triage')&&currentRole()!=='administrator'){toast('Lab Planner role is required to commit timing.',true);return}if(!mat.planningReady||!proc.ready){toast('Cannot commit timing until material feasibility and process/test definition are complete.',true);return}if(!r.triage?.forecastDate){toast('Run AUTO-PLAN before committing the timing forecast.',true);return}const forecast=r.triage.forecastDate,current=r.currentCommitmentDate||r.originalCommitmentDate;if(r.originalCommitmentDate&&current&&forecast!==current){const ctx=r.pendingReplanContext||{},events=(App.state.planningEvents||[]).filter(x=>x.active!==false||x.id===ctx.eventId);openModal(`Commit replan · ${r.id}`,`<div class="callout warn"><h3>Committed date movement requires a reason</h3><p>Original commitment <strong>${P.formatDate(r.originalCommitmentDate)}</strong> · current commitment <strong>${P.formatDate(current)}</strong> · proposed commitment <strong>${P.formatDate(forecast)}</strong>. The original date will never be overwritten.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Reason category</label><select id="replanCategory">${['Vacation / staff absence','Equipment outage','Lab closure / capacity loss','Calibration / maintenance','Material delay','Process / test development','Scope / quantity change','Engineering change','Priority change','Quality / rework','Capacity / congestion','Other'].map(x=>`<option ${ctx.reasonCategory===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Linked planning situation</label><select id="replanEvent"><option value="">None / not applicable</option>${events.map(x=>`<option value="${x.id}" ${ctx.eventId===x.id?'selected':''}>${esc(planningSituationLabel(x))}</option>`).join('')}</select></div><div class="field full"><label>Reason / explanation <small>required</small></label><textarea id="replanReason" placeholder="What caused the commitment to move?">${esc(ctx.reason||'')}</textarea></div></div>`,`${btn('Keep current commitment','data-modal-close','button')}${btn('Accept new commitment','data-accept-replan','button primary')}`,true);setTimeout(()=>{$('[data-accept-replan]').onclick=async()=>{const reason=$('#replanReason').value.trim(),category=$('#replanCategory').value,eventId=$('#replanEvent').value||null;if(!reason){toast('Every replan requires an explanation.',true);return}try{P.recordCommitment(App.state,r,forecast,{reasonCategory:category,reason,eventId})}catch(e){toast(e.message,true);return}const prev=r.status;r.triage.status='Committed';r.status=r.currentGate='LAB TRIAGE';r.pendingReplanContext=null;App.state.actions=App.state.actions.filter(a=>!(a.requestId===id&&/triage|timing|feasibility/i.test(a.title)));P.audit(App.state,'Lab timing replanned & committed','Request',id,current,forecast,`${category} · ${reason}`);await persist();closeModal();render();toast(`Replan committed. New commitment ${P.formatDate(forecast)}; original ${P.formatDate(r.originalCommitmentDate)} retained.`)}},0);return}const rec=P.recordCommitment(App.state,r,forecast);const prev=r.status;r.triage.status='Committed';r.status=r.currentGate='LAB TRIAGE';r.pendingReplanContext=null;App.state.actions=App.state.actions.filter(a=>!(a.requestId===id&&/triage|timing|feasibility/i.test(a.title)));P.audit(App.state,rec.type==='initial'?'Lab timing committed':'Lab timing recommitted','Request',id,prev,'LAB TRIAGE',`Forecast ${forecast}; original commitment ${r.originalCommitmentDate}; margin ${r.triage.slackDays} days`);await persist();render();toast(rec.type==='initial'?`Initial lab commitment recorded: ${P.formatDate(forecast)}.`:'Timing commitment confirmed with no date movement.')}

async function confirmRoute(id){const route=App.state.routes.find(x=>x.requestId===id),r=requestById(id);if(!route){toast('No route found.',true);return}if(!can('route:edit')&&currentRole()!=='administrator'){toast('Process Engineer role is required to confirm the route.',true);return}route.proposed=false;route.confirmed=true;route.assessedAt=P.now();route.steps.forEach(s=>{if(s.status==='Proposed')s.status='Planned'});if(['SUBMITTED','FEASIBILITY'].includes(r.status))r.status=r.currentGate='PROCESS DEFINITION';P.audit(App.state,'Process route assessed and confirmed','Request',id,'Proposed route','Confirmed route',`Route ${route.revision}; standard/new/modified decisions retained`);await persist();render();toast('Route confirmed. Complete any process/test development planning inputs before AUTO-PLAN.')}
async function closeRequest(id){const r=requestById(id);if(r.status!=='DELIVERED'){toast('Request can only close after delivery acknowledgement.',true);return}if(App.state.deviations.some(d=>d.requestId===id&&d.releaseHold&&d.status!=='CLOSED')){toast('Cannot close while release holds remain open.',true);return}new P.LearningService().captureBuild(App.state,id);const prev=r.status;r.status=r.currentGate='CLOSED';r.archived=true;r.archivedAt=P.now();r.closedAt=P.now();P.audit(App.state,'Prototype request closed & learning captured','Request',id,prev,'CLOSED','Delivery acknowledged; actual duration/yield/rework/issues retained for future same-product planning');await persist();render();toast('Request closed and archived. It remains searchable under Prototype Requests → Archived.')}
function changeAssuranceModal(requestId){const r=requestById(requestId),current=P.ensureAssuranceProfile(r),opts=Object.values(P.ASSURANCE_PROFILES);openModal('Change build purpose / assurance level',`<div class="callout"><h3>Scale the process to the purpose of the build</h3><p>Choose the lowest level that still provides the evidence you actually need. Product-safety-relevant work cannot be reduced below Validation.</p></div><div class="assurance-choice-grid" style="margin-top:12px">${opts.map(x=>`<label class="assurance-choice level-${x.formalLevel}"><input type="radio" name="assuranceChange" value="${x.id}" ${x.id===current.id?'checked':''}><strong>${esc(x.code)} · ${esc(x.label)}</strong><span>${esc(x.tagline)}</span><small>${esc(x.description)}</small></label>`).join('')}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Apply level','data-save-assurance','button primary')}`,true);setTimeout(()=>{$('[data-save-assurance]').onclick=async()=>{let id=$('input[name="assuranceChange"]:checked')?.value||current.id;if(r.productSafety&&P.ASSURANCE_PROFILES[id].formalLevel<2){toast('Product-safety-relevant builds require at least Validation.',true);id='validation'}const prev=r.assuranceProfile;r.assuranceProfile=id;P.ensureApprovalRecords(App.state,r);const route=App.state.routes.find(x=>x.requestId===requestId);if(route)route.confirmed=false;r.triage=null;r.forecastDate=null;P.audit(App.state,'Build assurance level changed','Request',requestId,prev,id,'Purpose/formality changed; route and timing require reconfirmation');await persist();closeModal();render();toast(`Build purpose changed to ${P.ASSURANCE_PROFILES[id].label}. Reconfirm route and timing.`)}} ,0)}
function showReadiness(id){const rs=new P.ReadinessService(App.state).evaluate(id);openModal('Build Readiness Review',`<div class="callout ${rs.ready?'':'warn'}"><h3>${rs.ready?'READY':'NOT READY'}</h3><p>${rs.ready?'Configured readiness conditions are satisfied.':'Resolve the exact blockers below. Passing the gate requires objective evidence, not a Complete button.'}</p></div><div style="height:10px"></div>${readinessRows(rs.checks)}${rs.issues.map(blockerBox).join('')}`,btn('Close','data-modal-close','button'))}
function routeStepsFromProcessIds(ids){return (ids||[]).map((pid,i)=>{const p=App.state.processes.find(x=>x.id===pid);return {id:P.uid('STEP'),order:i+1,processId:pid,name:p?.name||pid,processRevision:p?.revision||'A',type:'standard',owner:'Unassigned',planned:null,status:'Proposed',readiness:'pending',parallelGroup:null,optional:false}})}
function resetCopiedStep(s,i){const p=App.state.processes.find(x=>x.id===s.processId);return {...P.deepClone(s),id:P.uid('STEP'),order:i+1,name:p?.name||s.name,processRevision:p?.revision||s.processRevision||'A',status:'Proposed',readiness:s.type==='standard'?'pending':'blocked',planned:null,startedAt:null,startedBy:null,completedAt:null,completedBy:null,equipmentId:null,executionSerial:null,evidence:null,actualDurationHours:null}}
function routeSourceModal(requestId){const r=requestById(requestId),route=App.state.routes.find(x=>x.requestId===requestId),product=App.state.products.find(p=>p.id===r.productId);const prior=App.state.routes.filter(x=>x.requestId!==requestId&&x.steps?.length).map(x=>{const q=requestById(x.requestId);return {route:x,request:q}}).sort((a,b)=>(b.request?.productId===r.productId)-(a.request?.productId===r.productId));openModal('Choose build route starting point',`<div class="route-choice-grid"><label class="route-choice"><input type="radio" name="routeMode" value="scratch"><strong>Start from scratch</strong><span>Blank route. Add only the operations needed for this build.</span></label><label class="route-choice"><input type="radio" name="routeMode" value="product" checked><strong>Use product standard route</strong><span>${esc(product?.family||r.productFamily)} default · ${(product?.defaultRoute||[]).length} step(s). You can edit it freely for this build.</span></label><label class="route-choice"><input type="radio" name="routeMode" value="previous"><strong>Copy a previous build</strong><span>Reuse a route that worked before, then modify it without changing the original build record.</span></label></div><div id="routePreviousPick" class="field hidden" style="margin-top:14px"><label>Previous build route</label><select id="routePrevious">${prior.map(x=>`<option value="${x.route.requestId}">${x.request?.productId===r.productId?'★ ':''}${esc(x.route.requestId)} · ${esc(x.request?.productFamily||'Unknown product')} · ${x.route.steps.length} steps</option>`).join('')}</select><small>★ Same product family is listed first.</small></div><div class="callout" style="margin-top:14px"><h3>This is a starting point, not a locked template</h3><p>The selected route is copied into this request. From then on it can be reordered, extended, shortened, or individual steps can be changed to standard / modified / new methods.</p></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Use selected route',`data-apply-route-source="${requestId}"`,'button primary')}`,true);setTimeout(()=>{const radios=$$('input[name="routeMode"]'),pick=$('#routePreviousPick');radios.forEach(x=>x.onchange=()=>pick.classList.toggle('hidden',x.value!=='previous'||!x.checked));$(`[data-apply-route-source="${requestId}"]`).onclick=async()=>{const mode=$('input[name="routeMode"]:checked')?.value||'product';let steps=[],source={mode};if(mode==='scratch')steps=[];else if(mode==='product'){steps=routeStepsFromProcessIds(product?.defaultRoute?.length?product.defaultRoute:P.getDefaultRoute(r.productId));source.productId=r.productId;}else{const srcId=$('#routePrevious')?.value,src=App.state.routes.find(x=>x.requestId===srcId);if(!src){toast('Choose a previous route.',true);return}steps=src.steps.map(resetCopiedStep);source={mode:'previous',requestId:srcId,revision:src.revision};}route.steps=steps;route.revision=String.fromCharCode((route.revision||'A').charCodeAt(0)+1);route.confirmed=false;route.proposed=true;route.source=source;route.reworkLoops=[];route.steps.forEach((s,i)=>s.order=i+1);P.audit(App.state,'Build route starting point changed','Request',requestId,'Previous request route',mode,mode==='scratch'?'Started from blank route':mode==='product'?`Copied product standard route ${r.productId}`:`Copied route from ${source.requestId}`);await persist();closeModal();render();toast('Route copied into this build. Edit it as needed, then confirm it for planning.')}} ,0)}
function editRouteStepModal(stepId){const route=App.state.routes.find(r=>r.requestId===App.workspaceId),s=route?.steps.find(x=>x.id===stepId);if(!s)return;const options=App.state.processes.filter(p=>p.status==='Released'||p.id===s.processId).map(p=>`<option value="${p.id}" ${p.id===s.processId?'selected':''}>${esc(p.id)} · ${esc(p.name)} · Rev ${esc(p.revision)}</option>`).join('');openModal(`Edit route step ${s.order}`,`<div class="form-grid"><div class="field full"><label>Process / operation</label><select id="ersProc">${options}</select></div><div class="field"><label>Fit decision</label><select id="ersType"><option value="standard" ${s.type==='standard'?'selected':''}>Existing standard process</option><option value="modified" ${s.type==='modified'?'selected':''}>Modify / adapt this process</option><option value="new" ${s.type==='new'?'selected':''}>New process required</option></select></div><div class="field"><label>Owner</label><select id="ersOwner">${App.state.staff.map(st=>`<option ${st.name===s.owner?'selected':''}>${esc(st.name)}</option>`).join('')}</select></div><div class="field"><label><input id="ersOptional" type="checkbox" style="width:auto;min-height:auto" ${s.optional?'checked':''}> Optional operation</label></div><div class="field"><label><input id="ersParallel" type="checkbox" style="width:auto;min-height:auto" ${s.parallelGroup?'checked':''}> Parallel with adjacent branch</label></div></div><div class="callout warn" style="margin-top:12px"><h3>Changing a confirmed route reopens route review</h3><p>The original audit history is retained. Modified/new choices create or retain a development action appropriate to the selected build assurance level.</p></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save route step','data-save-route-step','button primary')}`);setTimeout(()=>{$('[data-save-route-step]').onclick=async()=>{const p=App.state.processes.find(x=>x.id===$('#ersProc').value),old=`${s.processId}/${s.type}`,type=$('#ersType').value;s.processId=p.id;s.name=p.name;s.processRevision=p.revision;s.type=type;s.owner=$('#ersOwner').value;s.optional=$('#ersOptional').checked;if($('#ersParallel').checked){s.parallelGroup=s.parallelGroup||P.uid('PAR')}else s.parallelGroup=null;s.readiness=type==='standard'?'pending':'blocked';route.confirmed=false;route.proposed=true;if(type!=='standard'&&!App.state.processDevelopments.some(d=>d.requestId===App.workspaceId&&d.stepId===s.id)){App.state.processDevelopments.push({id:P.uid('DEV'),requestId:App.workspaceId,stepId:s.id,name:`${p.name} — ${type==='modified'?'Adaptation':'New method'}`,status:'NEED IDENTIFIED',owner:s.owner,libraryCandidate:p.id,fitAssessment:[['Equipment capability','pass'],['Requested envelope','warn']],conclusion:type==='modified'?'MODIFIED PROCESS REQUIRED':'NEW PROCESS REQUIRED',trials:[],planningEstimateHours:0,gates:{need:true,plan:false,trial:false,parameters:false,risk:false,measurement:false,capability:false,controlPlan:false,workInstruction:false,approval:false,release:false}})}P.audit(App.state,'Route step edited','Request',App.workspaceId,old,`${s.processId}/${s.type}`,`Step ${s.order}`);await persist();closeModal();render();toast('Route step updated; reconfirm the route before committing timing.')}} ,0)}
async function moveRouteStep(stepId,delta){const route=App.state.routes.find(r=>r.requestId===App.workspaceId),i=route?.steps.findIndex(x=>x.id===stepId);if(i<0)return;const j=i+delta;if(j<0||j>=route.steps.length)return;[route.steps[i],route.steps[j]]=[route.steps[j],route.steps[i]];route.steps.forEach((x,k)=>x.order=k+1);route.confirmed=false;route.proposed=true;P.audit(App.state,'Route step reordered','Request',App.workspaceId,i+1,j+1,route.steps[j].name);await persist();render()}
