function showProcess(id){const p=App.state.processes.find(x=>x.id===id);openModal(`${p.id} · ${p.name}`,`<div class="grid cols-2"><div class="card"><h3>Released definition</h3>${[['Revision',p.revision],['Status',p.status],['Owner',p.owner],['Family',p.family],['Setup time',p.setupTime+' min'],['Cycle time',p.cycleTime+' min / '+p.basis],['Equipment',p.equipmentCapability],['Competency',p.competency]].map(([a,b])=>`<div class="score-row"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}</div><div class="card"><h3>Controlled content</h3><p>${esc(p.description)}</p><h3>Work instruction</h3><p><strong>${esc(p.workInstruction?.id||'Missing')}</strong> · ${esc(p.workInstruction?.status||'Missing')}</p><ol>${(p.workInstruction?.steps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>Required evidence</h3>${(p.requiredEvidence||[]).map(x=>`<div class="score-row"><span>${esc(x)}</span><span class="check">✓</span></div>`).join('')}</div></div>`,btn('Close','data-modal-close','button'),true)}
function editRequestModal(id){
 const r=requestById(id);if(!r)return;if(!canEditRequest(r)){toast('Engineering Requester, Engineering Project Lead or Administrator is required to edit the request.',true);return}
 const profile=P.ensureAssuranceProfile(r),product=App.state.products.find(p=>p.id===r.productId),advanced=P.GATES.indexOf(r.currentGate)>=P.GATES.indexOf('PROCESS DEFINITION');
 openModal(`Edit prototype request · ${r.id}`,`<div class="callout ${advanced?'warn':''}"><h3>${advanced?'Controlled change to an active request':'Engineering request details'}</h3><p>${advanced?'Changes remain in the audit/change history. Scope changes reopen the affected feasibility and timing so an obsolete forecast cannot remain committed.':'Correct missing or incorrect engineering inputs here. A missing objective can therefore be fixed without recreating the request.'}</p></div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>Request title</label><input id="erqTitle" value="${esc(r.title||'')}"></div><div class="field full"><label>Engineering objective <b>· required</b></label><textarea id="erqObjective" placeholder="What decision, learning or validation must this build enable?">${esc(r.objective||'')}</textarea><small>The objective is required because it determines the appropriate route, characterisation and evidence level.</small></div><div class="field"><label>Product</label><input value="${esc(product?.family||r.productFamily)} · ${esc(product?.partNumber||'')}" disabled><small>Product identity is locked after request creation; revision/configuration can still be changed below.</small></div><div class="field"><label>Quantity</label><input id="erqQty" type="number" min="1" value="${esc(r.quantity)}"></div><div class="field"><label>Engineering team</label><select id="erqTeam">${App.state.teams.map(t=>`<option ${r.engineeringTeam===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label>Customer / programme</label><select id="erqCust">${App.state.customers.map(c=>`<option value="${c.id}" ${r.customerId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Build purpose</label><select id="erqPurpose">${['Quick engineering experiment','Design learning / fit-check','Process learning','Correlation','Failure analysis','Design validation (DV)','Customer / validation sample','Production-intent / PPAP support'].map(x=>`<option ${r.purpose===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Assurance level</label><select id="erqAssurance">${Object.values(P.ASSURANCE_PROFILES).map(x=>`<option value="${x.id}" ${profile.id===x.id?'selected':''}>${x.code} · ${esc(x.label)}</option>`).join('')}</select><details class="help-task purpose-foldout" style="margin-top:8px"><summary>What does this level include?</summary><div class="help-body">${assuranceControlMatrix()}</div></details></div><div class="field"><label>Required delivery date</label><input id="erqDate" type="date" value="${esc(r.requiredDate||'')}"></div><div class="field"><label>Priority</label><select id="erqPriority">${['Critical','High','Normal','Low'].map(x=>`<option ${r.priority===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Delivery location</label><input id="erqLocation" value="${esc(r.deliveryLocation||'')}"></div><div class="field"><label>Product revision</label><input id="erqRev" value="${esc(r.productRevision||'')}"></div><div class="field"><label>Build maturity</label><select id="erqMaturity">${['Concept','A-sample','B-sample','C-sample'].map(x=>`<option ${r.maturity===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Build configuration</label><textarea id="erqConfig">${esc(r.configuration||'')}</textarea></div><div class="field"><label>BOM reference</label><input id="erqBom" value="${esc(r.bomRef||'')}"></div><div class="field"><label>Material source</label><select id="erqMat"><option ${r.materialOwnership==='Engineering supplied'?'selected':''}>Engineering supplied</option><option ${r.materialOwnership==='Lab supplied'?'selected':''}>Lab supplied</option></select></div><div class="field"><label><input id="erqSafety" type="checkbox" style="width:auto;min-height:auto" ${r.productSafety?'checked':''}> Product-safety relevant</label></div><div class="field full"><label>Requested characterisation / results <small>one per line</small></label><textarea id="erqChar">${esc((r.characterisation||[]).join('\n'))}</textarea></div><div class="field full"><label>Known special characteristics <small>one per line</small></label><textarea id="erqSC">${esc((r.specialCharacteristics||[]).join('\n'))}</textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save request changes','data-save-request-edit','button primary')}`,true);
 setTimeout(()=>{$('[data-save-request-edit]').onclick=async()=>{const objective=$('#erqObjective').value.trim(),title=$('#erqTitle').value.trim(),qty=Number($('#erqQty').value),date=$('#erqDate').value;if(!title||!objective||!date||qty<1){toast('Title, engineering objective, quantity and required date are required.',true);return}const before=P.deepClone(r),newAssurance=$('#erqSafety').checked&&P.ASSURANCE_PROFILES[$('#erqAssurance').value]?.formalLevel<2?'validation':$('#erqAssurance').value;Object.assign(r,{title,objective,quantity:qty,engineeringTeam:$('#erqTeam').value,customerId:$('#erqCust').value,purpose:$('#erqPurpose').value,assuranceProfile:newAssurance,requiredDate:date,priority:$('#erqPriority').value,deliveryLocation:$('#erqLocation').value.trim(),productRevision:$('#erqRev').value.trim(),maturity:$('#erqMaturity').value,configuration:$('#erqConfig').value.trim(),bomRef:$('#erqBom').value.trim(),materialOwnership:$('#erqMat').value,productSafety:$('#erqSafety').checked,characterisation:$('#erqChar').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),specialCharacteristics:$('#erqSC').value.split(/\n+/).map(x=>x.trim()).filter(Boolean)});P.ensureAssuranceProfile(r);P.ensureMaterialRequirements(App.state,r);(r.materialRequirements||[]).forEach(q=>q.requiredQty=Number(q.qtyPerUnit||1)*Number(r.quantity||1));if(r.materialOwnership==='Engineering supplied')r.materialSupply=r.materialSupply||{owner:r.requester||App.state.identity.name,expectedDate:'',reference:''};else r.materialSupply=null;r.testRequirements=[];P.ensureTestRequirements(App.state,r);if(!r.productSafety)App.state.approvals=(App.state.approvals||[]).filter(a=>a.requestId!==r.id||a.type!=='Product Safety'||a.status==='Approved');P.ensureApprovalRecords(App.state,r);const planningFields=['objective','quantity','requiredDate','priority','configuration','bomRef','materialOwnership','productSafety','assuranceProfile','characterisation','specialCharacteristics'],changed=planningFields.filter(k=>JSON.stringify(before[k])!==JSON.stringify(r[k]));if(changed.length){r.triage=null;r.forecastDate=null;App.state.bookings=(App.state.bookings||[]).filter(b=>b.requestId!==r.id);r.changeHistory=r.changeHistory||[];r.changeHistory.unshift({id:P.uid('CHG'),date:P.now(),type:'Engineering request update',from:changed.map(k=>`${k}: ${JSON.stringify(before[k])}`).join(' | '),to:changed.map(k=>`${k}: ${JSON.stringify(r[k])}`).join(' | '),impact:['Re-assess material/process/test feasibility','Re-run AUTO-PLAN before committing timing'],status:'Open'});App.state.actions.unshift({id:P.uid('ACT'),requestId:r.id,category:'Needs feasibility input',title:'Request changed — reassess feasibility and timing',why:`Engineering changed: ${changed.join(', ')}.`,impact:'Previous timing is no longer treated as committed until AUTO-PLAN is rerun.',owner:App.state.users.find(u=>u.role==='lab_planner')?.name||'Lab Planner',due:r.requiredDate,severity:'warn',resolve:'materials'});}P.audit(App.state,'Prototype request edited','Request',r.id,JSON.stringify(before),JSON.stringify(r),`Fields changed: ${changed.join(', ')||'descriptive fields'}`);await persist();closeModal();render();toast(changed.length?'Request updated. Affected feasibility/timing has been reopened.':'Request updated.');}},0)
}
function openRequestWizard(){App.wizardStep=0;App.wizardData={priority:'Normal',quantity:1,productId:App.state.products[0].id,customerId:'CUST-INTERNAL',engineeringTeam:App.state.teams[0],requiredDate:new Date(Date.now()+14*86400000).toISOString().slice(0,10),characterisation:['Functional verification'],materialOwnership:'Engineering supplied',materialSupplyOwner:App.state.identity.name,purpose:'Design learning / fit-check',assuranceProfile:'controlled'};renderWizard()}
function renderWizard(){const steps=['WHAT DO YOU NEED?','WHY DO YOU NEED IT?','WHEN DO YOU NEED IT?','WHAT CONFIGURATION?','WHAT CHARACTERISATION?','REVIEW & SUBMIT'];let body='';const d=App.wizardData,s=App.wizardStep;if(s===0)body=`<div class="form-grid"><div class="field full"><label>Request title</label><input id="wTitle" value="${esc(d.title||'')}"></div><div class="field"><label>Product/device</label><select id="wProduct">${App.state.products.map(p=>`<option value="${p.id}" ${d.productId===p.id?'selected':''}>${esc(p.family)} · ${esc(p.partNumber)}</option>`).join('')}</select></div><div class="field"><label>Quantity</label><input id="wQty" type="number" min="1" value="${d.quantity||1}"></div><div class="field"><label>Engineering team</label><select id="wTeam">${App.state.teams.map(t=>`<option ${d.engineeringTeam===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label>Customer / programme profile</label><select id="wCust">${App.state.customers.map(c=>`<option value="${c.id}" ${d.customerId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div>`;else if(s===1){const profiles=Object.values(P.ASSURANCE_PROFILES),recommended=P.recommendAssuranceProfile(d);body=`<div class="field"><label>Engineering objective / why do you need it?</label><textarea id="wObjective">${esc(d.objective||'')}</textarea><small>State the decision, learning or validation this build must enable.</small></div><div class="field" style="margin-top:12px"><label>Build purpose</label><select id="wPurpose">${['Quick engineering experiment','Design learning / fit-check','Process learning','Correlation','Failure analysis','Design validation (DV)','Customer / validation sample','Production-intent / PPAP support'].map(x=>`<option ${d.purpose===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label>Assurance / formality level</label><select id="wAssurance">${profiles.map(x=>`<option value="${x.id}" ${d.assuranceProfile===x.id?'selected':''}>${x.code} · ${esc(x.label)}</option>`).join('')}</select><small id="wAssuranceHint">Recommended from purpose: ${esc(P.ASSURANCE_PROFILES[recommended].code)} · ${esc(P.ASSURANCE_PROFILES[recommended].label)}. You may deliberately choose a different level; Product Safety automatically enforces at least Validation.</small></div><details class="help-task purpose-foldout" style="margin-top:12px"><summary>What do E0 / E1 / V / P include?</summary><div class="help-body">${assuranceControlMatrix()}</div></details>`}else if(s===2)body=`<div class="form-grid"><div class="field"><label>Required delivery date</label><input id="wDate" type="date" value="${esc(d.requiredDate)}"></div><div class="field"><label>Priority</label><select id="wPriority">${['Critical','High','Normal','Low'].map(x=>`<option ${d.priority===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Delivery location</label><input id="wLocation" value="${esc(d.deliveryLocation||'Enschede Engineering')}"></div></div>`;else if(s===3)body=`<div class="form-grid"><div class="field"><label>Product revision</label><input id="wRev" value="${esc(d.productRevision||App.state.products.find(p=>p.id===d.productId)?.revision||'A')}"></div><div class="field"><label>Build maturity</label><select id="wMaturity">${['Concept','A-sample','B-sample','C-sample'].map(x=>`<option ${d.maturity===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Build configuration</label><textarea id="wConfig">${esc(d.configuration||'')}</textarea></div><div class="field"><label>BOM reference</label><input id="wBom" value="${esc(d.bomRef||'')}"></div><div class="field"><label>Material source</label><select id="wMatOwn"><option ${d.materialOwnership==='Engineering supplied'?'selected':''}>Engineering supplied</option><option ${d.materialOwnership==='Lab supplied'?'selected':''}>Lab supplied</option></select><small>Engineering supplied = engineering owns arrival to the lab. Lab supplied = planner reserves exact matching lab stock.</small></div><div id="wEngSupply" class="field full ${d.materialOwnership==='Lab supplied'?'hidden':''}"><div class="form-grid"><div class="field"><label>Who will supply it?</label><input id="wMatOwner" value="${esc(d.materialSupplyOwner||App.state.identity.name)}"></div><div class="field"><label>Expected arrival at lab</label><input id="wMatDate" type="date" value="${esc(d.materialSupplyDate||'')}"></div><div class="field full"><label>Supply/reference note</label><input id="wMatRef" value="${esc(d.materialSupplyReference||'')}" placeholder="e.g. parts held by design engineer / shipment reference"></div></div></div><div class="field full"><label><input id="wSafety" type="checkbox" style="width:auto;min-height:auto" ${d.productSafety?'checked':''}> Product-safety relevant</label></div></div>`;else if(s===4)body=`<div class="field"><label>Requested characterisation / required results</label><textarea id="wChar">${esc((d.characterisation||[]).join('\n'))}</textarea><small>One per line. Released lab standards currently include: ${(App.state.standardTests||[]).map(x=>esc(x.name)).join(', ')}. Unmatched requests will require a test-development estimate before planning.</small></div><div class="field" style="margin-top:12px"><label>Known special characteristics</label><textarea id="wSC">${esc((d.specialCharacteristics||[]).join('\n'))}</textarea></div>`;else body=`<div class="callout"><h3>Review before submission</h3><p>The request creates a controlled Draft. After submission the practical sequence is: material feasibility → process/test assessment → resource-based timing → controls/readiness → build.</p></div><div class="grid cols-2" style="margin-top:12px">${[['Need',`${d.quantity} × ${App.state.products.find(p=>p.id===d.productId)?.family}`],['Objective',d.objective||'—'],['Required date',P.formatDate(d.requiredDate)],['Priority',d.priority],['Material source',d.materialOwnership],['Assurance',`${P.ASSURANCE_PROFILES[d.assuranceProfile||P.recommendAssuranceProfile(d)].code} · ${P.ASSURANCE_PROFILES[d.assuranceProfile||P.recommendAssuranceProfile(d)].label}`],['Characterisation',(d.characterisation||[]).join(', ')||'—']].map(([a,b])=>`<div class="card"><div class="subtle">${esc(a)}</div><strong>${esc(b)}</strong></div>`).join('')}</div>`;openModal(`New prototype request · ${steps[s]}`,`<div class="wizard-shell"><div class="wizard-progress">${steps.map((_,i)=>`<div class="wizard-step ${i<s?'done':''} ${i===s?'active':''}"></div>`).join('')}</div>${body}</div>`,s===0?`${btn('Cancel','data-modal-close','button')}${btn('Next →','data-w-next','button primary')}`:s<steps.length-1?`${btn('Back','data-w-back','button')}${btn('Next →','data-w-next','button primary')}`:`${btn('Back','data-w-back','button')}${btn('Create draft','data-w-create','button primary')}`,true);bindWizard();}
function captureWizard(){const d=App.wizardData,s=App.wizardStep;if(s===0){d.title=$('#wTitle').value.trim();d.productId=$('#wProduct').value;d.quantity=Number($('#wQty').value);d.engineeringTeam=$('#wTeam').value;d.customerId=$('#wCust').value}else if(s===1){d.objective=$('#wObjective').value.trim();d.purpose=$('#wPurpose').value;d.assuranceProfile=$('#wAssurance').value}else if(s===2){d.requiredDate=$('#wDate').value;d.priority=$('#wPriority').value;d.deliveryLocation=$('#wLocation').value}else if(s===3){d.productRevision=$('#wRev').value;d.maturity=$('#wMaturity').value;d.configuration=$('#wConfig').value;d.bomRef=$('#wBom').value;d.materialOwnership=$('#wMatOwn').value;d.materialSupplyOwner=$('#wMatOwner')?.value.trim()||'';d.materialSupplyDate=$('#wMatDate')?.value||'';d.materialSupplyReference=$('#wMatRef')?.value.trim()||'';d.productSafety=$('#wSafety').checked;if(d.productSafety&&P.ASSURANCE_PROFILES[d.assuranceProfile]?.formalLevel<2)d.assuranceProfile='validation'}else if(s===4){d.characterisation=$('#wChar').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);d.specialCharacteristics=$('#wSC').value.split(/\n+/).map(x=>x.trim()).filter(Boolean)}}
function bindWizard(){const back=$('[data-w-back]'),next=$('[data-w-next]'),create=$('[data-w-create]'),src=$('#wMatOwn'),purpose=$('#wPurpose'),assurance=$('#wAssurance');if(purpose&&assurance){purpose.onchange=()=>{const rec=P.recommendAssuranceProfile({...App.wizardData,purpose:purpose.value});assurance.value=rec;const h=$('#wAssuranceHint'),p=P.ASSURANCE_PROFILES[rec];if(h)h.textContent=`Recommended from purpose: ${p.code} · ${p.label}. You can deliberately select a different level; Product Safety enforces at least Validation.`}};if(src)src.onchange=()=>{$('#wEngSupply')?.classList.toggle('hidden',src.value!=='Engineering supplied')};if(back)back.onclick=()=>{captureWizard();App.wizardStep--;renderWizard()};if(next)next.onclick=()=>{captureWizard();if(App.wizardStep===0&&(!App.wizardData.title||App.wizardData.quantity<1)){toast('Add a request title and quantity.',true);return}App.wizardStep++;renderWizard()};if(create)create.onclick=async()=>{const req=new P.RequestService(App.state).create(App.wizardData);await persist();closeModal();openRequest(req.id);toast('Draft prototype request created.')}}
function createControlPlan(requestId){const r=requestById(requestId),route=App.state.routes.find(x=>x.requestId===requestId);const chars=(r.specialCharacteristics||[]).map((sc,i)=>({id:`${sc}-${i+1}`,processStep:route?.steps[Math.min(i,Math.max(0,(route?.steps.length||1)-1))]?.order||1,characteristic:sc,classification:'SC',target:'Define target',lsl:null,usl:null,unit:'',method:'',equipment:'',sampleSize:'100%',frequency:'Each unit',controlMethod:'To be defined',role:'Quality / Technician',reactionPlan:'Hold affected serial; notify Quality; disposition before release',evidence:'Guided build result'}));if(!chars.length)chars.push({id:P.uid('CHAR'),processStep:route?.steps[0]?.order||1,characteristic:'Prototype functional acceptance',classification:'',target:'Pass',lsl:null,usl:null,unit:'',method:'Functional verification',equipment:'Applicable released equipment',sampleSize:'100%',frequency:'Each unit',controlMethod:'Recorded pass/fail',role:'Technician',reactionPlan:'Hold on failure; open deviation',evidence:'Guided build result'});const cp={id:P.uid('CP'),name:`${r.productFamily} Prototype Control Plan`,revision:'A',phase:'Prototype',status:'Draft',owner:App.state.identity.name,approvedBy:null,approvedAt:null,requestIds:[requestId],characteristics:chars};App.state.controlPlans.push(cp);r.controlPlanId=cp.id;P.audit(App.state,'Control Plan created','Control Plan',cp.id,'—','Draft',`Linked to ${requestId}`);persist().then(()=>{render();toast('Draft Control Plan created and linked to request.')})}
function advanceGateModal(id){const r=requestById(id),idx=P.GATES.indexOf(r.currentGate),next=P.GATES[idx+1];if(!next){toast('No later gate is available.');return}openModal(`Gate review · ${r.currentGate} → ${next}`,`<div class="callout"><h3>Objective gate review</h3><p>Record the evidence reviewed. Build Readiness and Release gates also run hard guard-rail checks.</p></div><div style="height:12px"></div><div class="field"><label>Evidence / review conclusion</label><textarea id="gateEvidence" placeholder="What evidence was reviewed and what conclusion was reached?"></textarea></div><div class="field" style="margin-top:12px"><label>Reason / decision note</label><input id="gateReason" placeholder="Controlled decision note"></div>`,`${btn('Cancel','data-modal-close','button')}${btn(`Advance to ${next}`,`data-confirm-gate="${id}"`,'button primary')}`);setTimeout(()=>{$('[data-confirm-gate]').onclick=async()=>{const evidence=$('#gateEvidence').value.trim(),reason=$('#gateReason').value.trim();if(!evidence){toast('Gate advancement requires evidence/review conclusion.',true);return}if(r.currentGate==='BUILD READINESS REVIEW'){const rr=new P.ReadinessService(App.state).evaluate(id);const hasOverride=(r.overrides||[]).some(o=>o.scope.toLowerCase().includes('readiness'));if(!rr.ready&&!hasOverride){toast(`Build Readiness cannot pass: ${rr.issues.length} unresolved blocker(s).`,true);return}}if(r.currentGate==='RELEASE APPROVAL'){try{new P.QualityService(App.state).releaseRequest(id)}catch(e){toast(e.message,true);return}App.state.serials.filter(s=>s.requestId===id&&s.status!=='Hold').forEach(s=>s.releaseState='Released')}else{const prev=r.status;r.status=r.currentGate=next;P.audit(App.state,'Lifecycle gate advanced','Request',id,prev,next,`${reason||'Gate review'} · Evidence: ${evidence}`)}await persist();closeModal();render();toast(`Gate advanced to ${r.currentGate}.`)}} ,0)}
async function submitRequest(id){try{new P.RequestService(App.state).submit(id);await persist();render();toast('Request submitted to lab triage.')}catch(e){toast(e.message,true)}}
async function ackDelivery(id){const r=requestById(id);const prev=r.status;r.status=r.currentGate='DELIVERED';r.actualDeliveryDate=P.todayISO();App.state.serials.filter(s=>s.requestId===id&&s.releaseState==='Released').forEach(s=>{s.delivery=s.delivery||{date:r.actualDeliveryDate,recipient:App.state.identity.name,reference:P.uid('DEL')}});const cm=P.commitmentMetrics(r);P.audit(App.state,'Delivery acknowledged','Request',id,prev,'DELIVERED',`Actual ${r.actualDeliveryDate}; vs original ${cm.actualVsOriginalDays===null?'—':(cm.actualVsOriginalDays>0?'+':'')+cm.actualVsOriginalDays+' d'}; vs final ${cm.actualVsFinalDays===null?'—':(cm.actualVsFinalDays>0?'+':'')+cm.actualVsFinalDays+' d'}`);await persist();render();toast('Delivery acknowledged. Actual delivery date and commitment performance are now fixed for KPI tracking.')}
