async function releaseDevelopment(id){try{const newId=new P.ProcessService(App.state).releaseDevelopment(id);const dev=App.state.processDevelopments.find(d=>d.id===id);const route=App.state.routes.find(r=>r.requestId===dev.requestId);const step=route.steps.find(s=>s.type!=='standard'&&(s.processId===dev.libraryCandidate||dev.name.includes(s.name.split(' — ')[0])));if(step){const proc=App.state.processes.find(p=>p.id===newId);step.processId=newId;step.processRevision='A';step.type='standard';step.readiness='pending';step.name=proc.name}await persist();render();toast(`Process released as ${newId} Rev A.`)}catch(e){toast(e.message,true)}}
