 setTimeout(()=>{$('[data-save-measurement]').onclick=async()=>{const sampleRef=$('#mSerial').value,itemId=$('#mItem').value,c=mode==='cp'?chars.find(x=>x.id===itemId):null,t=mode==='end'?tests.find(x=>x.id===itemId):null,eq=App.state.equipment.find(e=>e.id===$('#mEq').value),value=Number($('#mValue').value);if(!sampleRef){toast('Select a sample.',true);return}if(!Number.isFinite(value)){toast('Enter a numeric result.',true);return}const m={id:P.uid('MEAS'),requestId,serial:sampleRef,measurementType:mode==='cp'?'control-plan':'end-characterisation',routeStepId:opts.stepId||null,testRequirementId:t?.id||null,characteristicId:c?.id||t?.id||P.uid('ENGRES'),characteristic:c?.characteristic||t?.name||'Engineering result',value,unit:c?.unit||$('#mUnit').value.trim(),lsl:c?.lsl??null,usl:c?.usl??null,target:c?.target??null,method:c?.method||App.state.standardTests.find(x=>x.id===t?.standardTestId)?.name||t?.name||'Engineering test',equipment:eq?.id||'Unspecified',equipmentCalibrationStatus:eq&&P.equipmentReady(eq,P.todayISO(),App.state)?'Valid':'Invalid',calibrationCertificateId:eq?P.validCalibrationCertificate(App.state,eq.id,P.todayISO())?.id||null:null,calibrationRequired:!!eq,operator:App.state.identity.name,timestamp:P.now(),pass:false,compliant:false,evidence:$('#mEvidence').value.trim()};m.pass=new P.QualityService(App.state).evaluateMeasurement(m);m.compliant=m.pass&&(!m.calibrationRequired||m.equipmentCalibrationStatus==='Valid');App.state.measurements.push(m);P.audit(App.state,mode==='cp'?'Control Plan measurement recorded':'End-characterisation result recorded','Request',requestId,'—',`${sampleDisplayFromRef(requestId,sampleRef)} · ${m.characteristic}=${value}`,m.pass?'Pass':'Action required');await persist();closeModal();render();toast(m.pass?'Traceable result recorded.':'Result recorded — action required.',!m.pass)}},0)
