function allocateMaterialModal(requestId){const r=requestById(requestId);P.ensureMaterialRequirements(App.state,r);const source=P.normaliseMaterialSource(r.materialOwnership),reqs=(r.materialRequirements||[]).map(req=>{const linked=App.state.allocations.filter(a=>a.requestId===requestId&&a.requirementId===req.id&&['Reserved','Issued'].includes(a.status)).reduce((n,a)=>n+Number(a.qty||0),0);return {...req,remaining:Math.max(0,Number(req.requiredQty||0)-linked)}}).filter(x=>x.remaining>0);if(!reqs.length){toast(source==='Lab supplied'?'All exact BOM requirements are already reserved/issued.':'All exact BOM requirements are already received/issued.');return}const options=reqs.map(req=>`<option value="${req.id}">${esc(req.partNumber)} Rev ${esc(req.revision)} · ${esc(req.description)} · need ${esc(req.remaining)} ${esc(req.unit)}</option>`).join('');if(source==='Engineering supplied'){openModal('Receive engineering-supplied material',`<div class="callout"><h3>Physical receipt creates genealogy</h3><p>Record the actual lot/batch and certificate/reference for the exact required BOM line. This converts the supply promise into build-ready traceability.</p></div><div style="height:12px"></div><div class="form-grid"><div class="field full"><label>Required BOM item</label><select id="aReq">${options}</select></div><div class="field"><label>Lot / batch</label><input id="aLot" placeholder="Engineering lot / supplier batch"></div><div class="field"><label>Quantity received</label><input id="aQty" type="number" min="1" value="1"></div><div class="field full"><label>Certificate / reference</label><input id="aCert" placeholder="CoC, engineering handover or source reference"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Receive & issue','data-save-eng-receipt','button primary')}`);setTimeout(()=>{$('[data-save-eng-receipt]').onclick=async()=>{const req=reqs.find(x=>x.id===$('#aReq').value),qty=Number($('#aQty').value),lot=$('#aLot').value.trim(),cert=$('#aCert').value.trim();if(!req||!lot||qty<=0||qty>req.remaining){toast('Enter a valid lot and receipt quantity within the exact BOM requirement.',true);return}const m={id:P.uid('MAT'),partNumber:req.partNumber,description:req.description,revision:req.revision,supplier:'Engineering supplied',lot,quantity:0,status:'Consumed / issued',certificate:cert,specialHandling:r.specialHandling||'Standard',expiry:null,received:P.todayISO()};App.state.materials.push(m);App.state.allocations.push({id:P.uid('ALLOC'),requestId,requirementId:req.id,materialId:m.id,lot,qty,status:'Issued'});P.audit(App.state,'Engineering material received & issued','Request',requestId,'Supply promise',`${req.partNumber} Rev ${req.revision} · ${lot}`,`${qty} ${req.unit}`);await persist();closeModal();render();toast('Engineering material received and linked to the exact build requirement.')}},0);return}
 openModal('Reserve exact lab-supplied material',`<div class="callout"><h3>Planning reservation</h3><p>Select the controlled BOM requirement first. Only the same part number and revision are offered. Reservation supports a credible plan; issue to build happens later at Build Readiness.</p></div><div style="height:12px"></div><div class="form-grid"><div class="field full"><label>Required BOM item</label><select id="aReq">${options}</select></div><div class="field full"><label>Matching lab lot</label><select id="aMat"></select></div><div class="field"><label>Quantity to reserve</label><input id="aQty" type="number" min="1" value="1"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Reserve for build','data-save-allocation','button primary')}`);const refresh=()=>{const req=reqs.find(x=>x.id===$('#aReq').value)||reqs[0],mats=App.state.materials.filter(m=>m.status==='Available'&&m.partNumber===req.partNumber&&m.revision===req.revision&&Number(m.quantity||0)>0);$('#aMat').innerHTML=mats.map(m=>`<option value="${m.id}">${esc(m.lot)} · stock ${esc(m.quantity)} · ${esc(m.certificate||'no certificate')}</option>`).join('')||'<option value="">No matching available lot</option>';$('#aQty').value=Math.min(req.remaining,1);$('#aQty').max=req.remaining};setTimeout(()=>{refresh();$('#aReq').onchange=refresh;$('[data-save-allocation]').onclick=async()=>{const req=reqs.find(x=>x.id===$('#aReq').value),m=App.state.materials.find(x=>x.id===$('#aMat').value),qty=Number($('#aQty').value);if(!req||!m||m.partNumber!==req.partNumber||m.revision!==req.revision){toast('No exact matching lab lot is available.',true);return}if(qty<=0||qty>req.remaining||qty>Number(m.quantity||0)){toast('Invalid reserve quantity.',true);return}App.state.allocations.push({id:P.uid('ALLOC'),requestId,requirementId:req.id,materialId:m.id,lot:m.lot,qty,status:'Reserved'});m.quantity-=qty;P.audit(App.state,'Lab material reserved','Request',requestId,'Available stock',`${req.partNumber} Rev ${req.revision} · ${m.lot}`,`${qty} ${req.unit}`);await persist();closeModal();render();toast('Exact lab material reserved for planning. Issue it before build start.')}},0)}
function materialSupplyModal(requestId){const r=requestById(requestId),s=r.materialSupply||{};openModal('Engineering material supply promise',`<div class="callout"><h3>Timing input, not receipt</h3><p>This tells the planner when the exact BOM material is expected at the lab. Build Readiness still requires physical lot receipt and issue.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Supply owner</label><input id="msOwner" value="${esc(s.owner||r.requester)}"></div><div class="field"><label>Expected lab arrival</label><input id="msDate" type="date" value="${esc(s.expectedDate||'')}"></div><div class="field full"><label>Reference / note</label><input id="msRef" value="${esc(s.reference||'')}"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save supply promise','data-save-material-supply','button primary')}`);setTimeout(()=>{$('[data-save-material-supply]').onclick=async()=>{const owner=$('#msOwner').value.trim(),date=$('#msDate').value;if(!owner||!date){toast('Supply owner and expected arrival date are required for planning.',true);return}r.materialSupply={owner,expectedDate:date,reference:$('#msRef').value.trim()};P.audit(App.state,'Engineering material supply promise updated','Request',requestId,'Previous supply basis',date,owner);await persist();closeModal();render();toast('Material timing basis saved.')}},0)}
async function issueReservedMaterials(requestId){const a=App.state.allocations.filter(x=>x.requestId===requestId&&x.status==='Reserved');if(!a.length){toast('No reserved material to issue.',true);return}a.forEach(x=>x.status='Issued');P.audit(App.state,'Reserved material issued to build','Request',requestId,'Reserved','Issued',`${a.length} exact BOM allocation(s)`);await persist();render();toast('Reserved lots issued to build genealogy.')}
async function reserveAllMaterials(requestId){const r=requestById(requestId);P.ensureMaterialRequirements(App.state,r);if(P.normaliseMaterialSource(r.materialOwnership)!=='Lab supplied'){toast('Bulk reservation is only used for Lab supplied material.',true);return}const created=[],short=[];for(const req of (r.materialRequirements||[])){const already=App.state.allocations.filter(a=>a.requestId===requestId&&a.requirementId===req.id&&['Reserved','Issued'].includes(a.status)).reduce((n,a)=>n+Number(a.qty||0),0);let remaining=Math.max(0,Number(req.requiredQty||0)-already);if(!remaining)continue;const lots=App.state.materials.filter(m=>m.status==='Available'&&m.partNumber===req.partNumber&&m.revision===req.revision&&Number(m.quantity||0)>0).sort((a,b)=>String(a.expiry||'9999').localeCompare(String(b.expiry||'9999'))||String(a.received||'').localeCompare(String(b.received||'')));for(const m of lots){if(!remaining)break;const qty=Math.min(remaining,Number(m.quantity||0));if(qty<=0)continue;App.state.allocations.push({id:P.uid('ALLOC'),requestId,requirementId:req.id,materialId:m.id,lot:m.lot,qty,status:'Reserved'});m.quantity-=qty;remaining-=qty;created.push(`${req.partNumber} Rev ${req.revision} · ${m.lot} × ${qty}`)}if(remaining>0)short.push(`${req.partNumber} Rev ${req.revision}: short ${remaining} ${req.unit||'pc'}`)}P.audit(App.state,'Bulk BOM reservation','Request',requestId,'Unreserved stock',`${created.length} lot allocation(s) reserved`,short.length?`Shortages: ${short.join('; ')}`:'All exact BOM requirements reserved');await persist();render();if(short.length)toast(`Reserved all available exact BOM stock. ${short.join(' · ')}`,true);else toast(`All exact BOM material reserved in ${created.length} lot allocation(s).`)}
function developmentEstimateModal(devId){const d=App.state.processDevelopments.find(x=>x.id===devId);openModal('Process-development planning estimate',`<div class="callout"><h3>Owned planning assumption</h3><p>Define the expected engineering effort needed before this process can be released. Future builds will replace assumptions with actual/historical data where available.</p></div><div class="field" style="margin-top:12px"><label>Development effort (hours)</label><input id="devHours" type="number" min="0.5" step="0.5" value="${esc(d.planningEstimateHours||'')}"></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save estimate','data-save-dev-estimate','button primary')}`);setTimeout(()=>{$('[data-save-dev-estimate]').onclick=async()=>{const h=Number($('#devHours').value);if(!h){toast('Enter a positive development effort.',true);return}d.planningEstimateHours=h;P.audit(App.state,'Process development estimate set','Process Development',devId,'—',`${h} h`,'Planning input owned by Process Engineering');await persist();closeModal();render();toast('Development allowance saved.')}},0)}
function selectEndTestsModal(requestId){const r=requestById(requestId);P.ensurePlanningModel(App.state);const selected=new Set((r.testRequirements||[]).map(x=>x.standardTestId).filter(Boolean)),custom=(r.testRequirements||[]).filter(x=>!x.standardTestId).map(x=>x.name);const tests=(App.state.standardTests||[]).filter(t=>t.status==='Released');openModal('Select end-characterisation tests',`<div class="callout"><h3>Reuse controlled lab test methods where possible</h3><p>Selected standard tests carry their setup/cycle time, equipment capability, certified skill and cost basis into AUTO-PLAN. Add a custom engineering result only when no released method fits.</p></div><div class="test-choice-list" style="margin-top:12px">${tests.map(t=>`<label class="test-choice"><input type="checkbox" data-test-choice value="${esc(t.id)}" ${selected.has(t.id)?'checked':''}><span><strong>${esc(t.id)} Rev ${esc(t.revision)} · ${esc(t.name)}</strong><small>${esc(t.setupTime)} min setup + ${esc(t.cycleTime)} min/${esc(t.basis)} · ${esc(t.equipmentCapability)} · ${esc(App.state.competencies?.find(c=>c.id===t.competency)?.name||t.competency)}</small></span></label>`).join('')}</div><div class="field" style="margin-top:12px"><label>Additional engineering-specific results <small>(one per line)</small></label><textarea id="customEndTests" placeholder="e.g. Visual comparison to reference">${esc(custom.join('\n'))}</textarea></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Apply selected tests','data-save-end-tests','button primary')}`,true);setTimeout(()=>{$('[data-save-end-tests]').onclick=async()=>{const ids=$$('[data-test-choice]:checked').map(x=>x.value),names=ids.map(id=>App.state.standardTests.find(t=>t.id===id)?.name).filter(Boolean),extra=$('#customEndTests').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);r.characterisation=[...names,...extra];r.testRequirements=[];P.ensureTestRequirements(App.state,r);r.triage=null;r.forecastDate=null;P.audit(App.state,'End-characterisation selection changed','Request',requestId,'Previous requested tests',r.characterisation.join('; '),'Planning must be refreshed');await persist();closeModal();render();toast(`${r.characterisation.length} end-characterisation requirement(s) selected. Re-run AUTO-PLAN.`)}},0)}
function testEstimateModal(requestId,testReqId){const r=requestById(requestId),tr=(r.testRequirements||[]).find(x=>x.id===testReqId);openModal(`Test development · ${tr.name}`,`<div class="callout"><h3>No released standard test matched</h3><p>For timing only, Process Engineering defines development effort and a provisional execution resource/skill. The method must still be released before Build Readiness.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Development effort (h)</label><input id="tdDev" type="number" min="0.5" step="0.5" value="${esc(tr.developmentEstimateHours||'')}"></div><div class="field"><label>Provisional execution time (h/build)</label><input id="tdExec" type="number" min="0.25" step="0.25" value="${esc(tr.executionEstimateHours||'')}"></div><div class="field"><label>Equipment capability</label><select id="tdEq">${[...new Set(App.state.equipment.map(e=>e.capability))].map(x=>`<option ${tr.equipmentCapability===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Required skill</label><select id="tdSkill">${(App.state.competencies||[]).map(x=>`<option value="${x.id}" ${tr.competency===x.id?'selected':''}>${esc(x.id)} · ${esc(x.name)}</option>`).join('')}</select></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save planning basis','data-save-test-estimate','button primary')}`);setTimeout(()=>{$('[data-save-test-estimate]').onclick=async()=>{const dh=Number($('#tdDev').value),eh=Number($('#tdExec').value);if(!dh||!eh){toast('Development and provisional execution hours are required.',true);return}Object.assign(tr,{developmentEstimateHours:dh,executionEstimateHours:eh,equipmentCapability:$('#tdEq').value,competency:$('#tdSkill').value,owner:App.state.identity.name,status:'Development planned'});P.audit(App.state,'Test development planning basis set','Request',requestId,'Unmapped test',tr.name,`${dh} h development + ${eh} h provisional execution`);await persist();closeModal();render();toast('Test development planning basis saved.')}},0)}
async function releaseTestDevelopment(requestId,testReqId){const r=requestById(requestId),tr=(r.testRequirements||[]).find(x=>x.id===testReqId);if(!tr?.developmentEstimateHours){toast('Define the development planning basis first.',true);return}tr.developmentReleased=true;tr.status='Released developed method';P.audit(App.state,'Developed test method released','Request',requestId,'Development planned','Released',tr.name);await persist();render();toast('Developed test method marked released for this prototype workflow.')}

function nextProcessRevision(rev){const r=String(rev||'A').trim().toUpperCase();if(/^[A-Y]$/.test(r))return String.fromCharCode(r.charCodeAt(0)+1);if(r==='Z')return 'AA';const m=r.match(/^([A-Z]+)(\d+)$/);if(m)return `${m[1]}${Number(m[2])+1}`;return `${r || 'A'}1`}
function editProcessDefinition(id){const p=App.state.processes.find(x=>x.id===id);if(!p)return;const released=p.status==='Released',wi=p.workInstruction||{id:`WI-${id}`,revision:p.revision||'A',title:`Work instruction · ${p.name}`,status:'Draft',steps:[]};openModal(`${released?'Revise':'Edit'} process · ${p.name}`,`${released?`<div class="callout warn"><h3>Released revision is protected</h3><p>Saving changes creates the next process revision Under review. Existing builds retain the process revision already recorded on their route/execution history.</p></div>`:`<div class="callout"><h3>Edit controlled process definition</h3><p>Update the process, planning basis, required certified skill and executable work instruction before release.</p></div>`}<div class="form-grid" style="margin-top:12px"><div class="field"><label>Process name</label><input id="epName" value="${esc(p.name)}"></div><div class="field"><label>Process family</label><input id="epFamily" value="${esc(p.family||'')}"></div><div class="field"><label>Owner</label><input id="epOwner" value="${esc(p.owner||App.state.identity.name)}"></div><div class="field"><label>Basis</label><select id="epBasis"><option ${p.basis==='Unit'?'selected':''}>Unit</option><option ${p.basis==='Batch'?'selected':''}>Batch</option></select></div><div class="field full"><label>Description / operating scope</label><textarea id="epDesc">${esc(p.description||'')}</textarea></div><div class="field"><label>Setup time (min)</label><input id="epSetup" type="number" min="0" value="${esc(p.setupTime||0)}"></div><div class="field"><label>Cycle time (min)</label><input id="epCycle" type="number" min="0" value="${esc(p.cycleTime||0)}"></div><div class="field"><label>Equipment capability</label><select id="epEq">${[...new Set(App.state.equipment.map(e=>e.capability))].map(x=>`<option ${p.equipmentCapability===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Required certified skill</label><select id="epSkill">${App.state.competencies.map(c=>`<option value="${c.id}" ${p.competency===c.id?'selected':''}>${esc(c.id)} · ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Fixed process charge (€)</label><input id="epFixed" type="number" min="0" step="0.01" value="${esc(p.fixedCharge||0)}"></div><div class="field"><label>Consumables (€ / ${esc(p.basis||'Unit')})</label><input id="epConsum" type="number" min="0" step="0.01" value="${esc(p.consumableCost||0)}"></div><div class="field full"><label>Work instruction title</label><input id="epWITitle" value="${esc(wi.title||`Work instruction · ${p.name}`)}"></div><div class="field full"><label>Work instruction steps — one per line</label><textarea id="epWI">${esc((wi.steps||[]).join('\n'))}</textarea></div><div class="field full"><label>Required evidence — one per line</label><textarea id="epEvidence">${esc((p.requiredEvidence||[]).join('\n'))}</textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn(released?'Create revised draft':'Save process','data-save-process-definition','button primary')}`,true);setTimeout(()=>{$('[data-save-process-definition]').onclick=async()=>{const name=$('#epName').value.trim(),desc=$('#epDesc').value.trim(),steps=$('#epWI').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),evidence=$('#epEvidence').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!name||!desc||steps.length<1||!$('#epEq').value||!$('#epSkill').value){toast('Name, scope, equipment capability, certified skill and at least one work-instruction step are required.',true);return}const prev=P.deepClone(p),oldRev=p.revision;if(released){p.revisionHistory=p.revisionHistory||[];p.revisionHistory.push({rev:oldRev,status:'Superseded by draft revision',date:P.todayISO(),note:'Controlled edit',snapshot:prev});p.revision=nextProcessRevision(oldRev);p.status='Under review';}Object.assign(p,{name,family:$('#epFamily').value.trim(),owner:$('#epOwner').value.trim(),description:desc,setupTime:Number($('#epSetup').value||0),cycleTime:Number($('#epCycle').value||0),basis:$('#epBasis').value,equipmentCapability:$('#epEq').value,competency:$('#epSkill').value,fixedCharge:Number($('#epFixed').value||0),consumableCost:Number($('#epConsum').value||0),requiredEvidence:evidence});p.workInstruction={...(p.workInstruction||{}),id:p.workInstruction?.id||`WI-${p.id}`,revision:p.revision,title:$('#epWITitle').value.trim()||`Work instruction · ${name}`,status:released?'Draft':(p.workInstruction?.status||'Draft'),steps};if(released){p.approvals=[]}P.audit(App.state,released?'Process revision created':'Process definition edited','Process',id,`Rev ${oldRev}`,`Rev ${p.revision} · ${p.status}`,released?'Released process changed through controlled revision':'Draft/under-review process updated');await persist();closeModal();render();toast(released?`Process revised to Rev ${p.revision} Under review.`:'Process definition updated.')}},0)}
function staffEditorModal(staffId=null){const existing=staffId?App.state.staff.find(x=>x.id===staffId):null,labRoles=['lab_planner','process_engineer','technician','quality','metrology','product_safety','lab_manager','approver'];const d=existing||{name:'',role:'technician',team:'Prototype Lab',available:true,employeeNo:'',email:'',qualification:'Independent',competencies:[],trainingCertificates:[]};openModal(existing?`Edit lab staff · ${d.name}`:'Add lab staff',`<div class="callout"><h3>Planning resource record</h3><p>This controls whether the person is available to AUTO-PLAN. Skills are not assigned here: each planning skill still requires a valid training certificate.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Name</label><input id="stName" value="${esc(d.name||'')}"></div><div class="field"><label>Employee / resource number</label><input id="stNo" value="${esc(d.employeeNo||d.id||'')}" placeholder="EMP-001"></div><div class="field"><label>Lab role</label><select id="stRole">${labRoles.map(r=>`<option value="${r}" ${d.role===r?'selected':''}>${esc(roleLabel(r))}</option>`).join('')}</select></div><div class="field"><label>Team</label><input id="stTeam" value="${esc(d.team||'Prototype Lab')}"></div><div class="field"><label>Email / contact</label><input id="stEmail" type="email" value="${esc(d.email||'')}"></div><div class="field"><label>Qualification level</label><select id="stQual">${['Observer','Supervised','Independent','Reviewer','Trainer'].map(q=>`<option ${d.qualification===q?'selected':''}>${q}</option>`).join('')}</select></div><div class="field full"><label><input id="stAvailable" type="checkbox" style="width:auto;min-height:auto" ${d.available!==false?'checked':''}> Available for lab planning</label><small>Use this for current availability. Training-certificate validity is checked separately by AUTO-PLAN.</small></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn(existing?'Save staff record':'Add staff','data-save-staff','button primary')}`);setTimeout(()=>{$('[data-save-staff]').onclick=async()=>{const name=$('#stName').value.trim();if(!name){toast('Staff name is required.',true);return}const prev=existing?P.deepClone(existing):null;if(existing){Object.assign(existing,{name,employeeNo:$('#stNo').value.trim()||existing.employeeNo||existing.id,role:$('#stRole').value,team:$('#stTeam').value.trim()||'Prototype Lab',email:$('#stEmail').value.trim(),qualification:$('#stQual').value,available:$('#stAvailable').checked});P.audit(App.state,'Lab staff updated','Staff',existing.id,prev.name,existing.name,`${roleLabel(existing.role)} · ${existing.available?'available':'unavailable'}`)}else{let n=1,id;do{id=`STAFF-${String(n++).padStart(3,'0')}`}while(App.state.staff.some(x=>x.id===id));const st={id,name,employeeNo:$('#stNo').value.trim()||id,role:$('#stRole').value,team:$('#stTeam').value.trim()||'Prototype Lab',email:$('#stEmail').value.trim(),qualification:$('#stQual').value,available:$('#stAvailable').checked,competencies:[],trainingCertificates:[]};App.state.staff.push(st);P.audit(App.state,'Lab staff added','Staff',id,'—',name,roleLabel(st.role))}await persist();closeModal();render();toast(existing?'Staff record updated.':'Staff added. Issue training certificates before AUTO-PLAN can use skill-gated work.')}},0)}
function readFileDataUrl(file){return new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=()=>reject(fr.error||new Error('Could not read certificate file'));fr.readAsDataURL(file)})}
function addCalibrationCertificateModal(id){const e=App.state.equipment.find(x=>x.id===id);if(!e)return;const defaultDue=new Date();defaultDue.setMonth(defaultDue.getMonth()+6);openModal(`Add calibration certificate · ${e.name}`,`<div class="callout"><h3>Certificate-backed calibration only</h3><p>A calibration is valid only when a passing, in-date certificate file is stored. New certificates are appended to history; earlier certificates are never overwritten.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Certificate number</label><input id="ccNo" placeholder="CAL-${esc(e.id)}-2026"></div><div class="field"><label>Calibration laboratory / issuer</label><input id="ccIssuer" placeholder="Calibration laboratory"></div><div class="field"><label>Calibration date</label><input id="ccDate" type="date" value="${P.todayISO()}"></div><div class="field"><label>Next due date</label><input id="ccDue" type="date" value="${defaultDue.toISOString().slice(0,10)}"></div><div class="field full"><label>Traceability / reference standard</label><input id="ccTrace" placeholder="Reference standard / traceability statement"></div><div class="field"><label>Result</label><select id="ccResult"><option>Pass</option><option>Limited use</option><option>Fail</option></select></div><div class="field"><label>Calibration certificate file <small>(required for valid status)</small></label><input id="ccFile" type="file" accept=".pdf,.jpg,.jpeg,.png,.txt"></div><div class="field full"><label>Controlled document reference</label><input id="ccEvidence" placeholder="Document ID / SharePoint / PLM reference"></div><div class="field full"><label>Comment</label><textarea id="ccComment">Calibration certificate recorded</textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Add certificate','data-save-cal-certificate','button primary')}`,true);setTimeout(()=>{$('[data-save-cal-certificate]').onclick=async()=>{try{const no=$('#ccNo').value.trim(),issuer=$('#ccIssuer').value.trim(),ev=$('#ccEvidence').value.trim(),file=$('#ccFile').files?.[0],result=$('#ccResult').value;if(!no||!issuer){toast('Certificate number and issuer are required.',true);return}if(result==='Pass'&&!file){toast('A passing calibration is only valid when the certificate file is uploaded.',true);return}const fileData=file?await readFileDataUrl(file):null;App.state.calibrationCertificates=App.state.calibrationCertificates||[];const cert={id:P.uid('CALCERT'),equipmentId:id,certificateNo:no,issuer,referenceStandard:$('#ccTrace').value.trim(),completedAt:$('#ccDate').value,nextDue:$('#ccDue').value,result,status:result==='Pass'?'Valid':'Attention',evidence:ev||file?.name||'',fileName:file?.name||'',fileType:file?.type||'',fileSize:file?.size||0,fileData,documentUploaded:!!fileData,comment:$('#ccComment').value.trim(),person:App.state.identity.name};App.state.calibrationCertificates.push(cert);App.state.maintenanceRecords=App.state.maintenanceRecords||[];App.state.maintenanceRecords.push({id:P.uid('CAL'),equipmentId:id,type:'Calibration',completedAt:cert.completedAt,nextDue:cert.nextDue,evidence:cert.evidence,comment:cert.comment,person:cert.person,certificateId:cert.id});e.calibrationStatus=result==='Pass'&&fileData?'Valid':'Invalid';e.calibrationDue=cert.nextDue;e.calibrationCertificateValid=!!P.validCalibrationCertificate(App.state,id,P.todayISO());for(const b of App.state.resourceCareBookings||[])if(b.status==='Scheduled'&&b.type==='Calibration'&&b.equipmentId===id)b.status='Completed';App.state.actions=(App.state.actions||[]).filter(a=>!(a.careType==='Calibration'&&a.objectId===id));P.audit(App.state,'Calibration certificate appended','Equipment',id,'Previous certificate history',no,`${issuer} · ${result} · ${file?.name||'no file'}`);await persist();closeModal();render();toast(`Calibration certificate ${no} added to history${e.calibrationCertificateValid?' and equipment is valid':' ; equipment remains unavailable'}.`,!e.calibrationCertificateValid)}catch(err){toast(`Certificate upload failed: ${err.message}`,true)}}},0)}
function editPlanningStandard(kind,id){const obj=kind==='process'?App.state.processes.find(x=>x.id===id):App.state.standardTests.find(x=>x.id===id);if(!obj)return;openModal(`Planning standard · ${obj.name}`,`<div class="callout"><h3>Lab Manager owned master data</h3><p>These values are the fallback planning standard. Same-product historical actuals are blended into future estimates automatically.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Setup time (min)</label><input id="psSetup" type="number" min="0" value="${esc(obj.setupTime)}"></div><div class="field"><label>Cycle time (min)</label><input id="psCycle" type="number" min="0" value="${esc(obj.cycleTime)}"></div><div class="field"><label>Basis</label><select id="psBasis"><option ${obj.basis==='Unit'?'selected':''}>Unit</option><option ${obj.basis==='Batch'?'selected':''}>Batch</option></select></div><div class="field"><label>Equipment capability</label><select id="psEq">${[...new Set(App.state.equipment.map(e=>e.capability))].map(x=>`<option ${obj.equipmentCapability===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Fixed charge (€)</label><input id="psFixed" type="number" min="0" value="${esc(obj.fixedCharge||0)}"></div><div class="field"><label>Consumables (€ / unit or batch)</label><input id="psConsum" type="number" min="0" value="${esc(obj.consumableCost||0)}"></div><div class="field full"><label>Required competency</label><select id="psSkill">${(App.state.competencies||[]).map(x=>`<option value="${x.id}" ${obj.competency===x.id?'selected':''}>${esc(x.id)} · ${esc(x.name)}</option>`).join('')}</select></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save planning standard','data-save-planning-standard','button primary')}`);setTimeout(()=>{$('[data-save-planning-standard]').onclick=async()=>{Object.assign(obj,{setupTime:Number($('#psSetup').value),cycleTime:Number($('#psCycle').value),basis:$('#psBasis').value,equipmentCapability:$('#psEq').value,competency:$('#psSkill').value,fixedCharge:Number($('#psFixed').value||0),consumableCost:Number($('#psConsum').value||0)});P.audit(App.state,'Lab planning standard updated',kind==='process'?'Process':'Standard Test',id,'Previous planning master data',`${obj.setupTime}/${obj.cycleTime} min`,App.state.identity.name);await persist();closeModal();render();toast('Lab planning standard updated.')}},0)}
function editStaffSkills(staffId){
 const st=App.state.staff.find(x=>x.id===staffId); if(!st)return;
 const certs=(App.state.trainingCertificates||[]).filter(c=>c.staffId===staffId).sort((a,b)=>String(b.issuedAt||'').localeCompare(String(a.issuedAt||'')));
 const expiryFor=(skillId,issued=P.todayISO())=>{const sk=App.state.competencies.find(x=>x.id===skillId),d=new Date(`${issued}T12:00:00`);d.setMonth(d.getMonth()+Number(sk?.validMonths||24));return d.toISOString().slice(0,10)};
 const initialSkill=App.state.competencies[0]?.id||'';
 const rows=certs.map(c=>{const current=c.status==='Valid'&&(!c.expiresAt||c.expiresAt>=P.todayISO());return `<div class="score-row"><span><strong>${esc(App.state.competencies.find(x=>x.id===c.skillId)?.name||c.skillId)}</strong><br><small>${esc(c.certificateNo)} · issuer ${esc(c.issuer||'—')} · issued ${P.formatDate(c.issuedAt)} · expires ${P.formatDate(c.expiresAt)}</small><br><small>${esc(c.evidence||'No evidence reference')}</small></span><span>${status(current?'Valid':c.status==='Valid'?'Expired':c.status||'Historical')} ${current?btn('Revoke',`data-revoke-staff-cert="${c.id}"`,'button tiny danger'):''}</span></div>`}).join('')||'<div class="empty">No competency certificates recorded.</div>';
 openModal(`Manage competencies · ${st.name}`,`<div class="callout"><h3>Certificate-gated competency management</h3><p>Edit the competency catalogue separately. For this person, issue/renew or revoke certificates here. AUTO-PLAN only uses competencies with a valid, in-date certificate.</p></div><div style="margin-top:12px">${rows}</div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Competency</label><select id="certSkill">${App.state.competencies.map(c=>`<option value="${c.id}">${esc(c.id)} · ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Certificate number</label><input id="certNo" placeholder="TR-2026-001"></div><div class="field"><label>Issuer / trainer</label><input id="certIssuer" value="${esc(App.state.identity.name)}"></div><div class="field"><label>Issue date</label><input id="certIssued" type="date" value="${P.todayISO()}"></div><div class="field"><label>Expiry date</label><input id="certExpiry" type="date" value="${expiryFor(initialSkill)}"></div><div class="field"><label>Evidence / certificate reference</label><input id="certEvidence" placeholder="Certificate / LMS record"></div></div>`,`${btn('Close','data-modal-close','button')}${btn('Issue / renew competency','data-issue-certificate','button primary')}`,true);
 setTimeout(()=>{
  const skill=$('#certSkill'),issued=$('#certIssued'),expiry=$('#certExpiry');
  const syncExpiry=()=>{if(skill&&issued&&expiry&&issued.value)expiry.value=expiryFor(skill.value,issued.value)};
  if(skill)skill.onchange=syncExpiry; if(issued)issued.onchange=syncExpiry;
  $$('[data-revoke-staff-cert]').forEach(el=>el.onclick=async()=>{const c=App.state.trainingCertificates.find(x=>x.id===el.dataset.revokeStaffCert);if(!c)return;if(!confirm(`Revoke ${App.state.competencies.find(x=>x.id===c.skillId)?.name||c.skillId} for ${st.name}?`))return;c.status='Revoked';c.revokedAt=P.now();c.revokedBy=App.state.identity.name;P.audit(App.state,'Training certificate revoked','Staff',staffId,c.skillId,'Revoked',`${c.certificateNo}; ${App.state.identity.name}`);await persist();closeModal();render();toast('Competency certificate revoked; AUTO-PLAN will no longer use it.');});
  const issue=$('[data-issue-certificate]');if(issue)issue.onclick=async()=>{const skillId=$('#certSkill').value,no=$('#certNo').value.trim(),ev=$('#certEvidence').value.trim(),issuedAt=$('#certIssued').value,expiresAt=$('#certExpiry').value;if(!no||!ev||!issuedAt||!expiresAt){toast('Certificate number, issue/expiry dates and evidence are required.',true);return}if(expiresAt<issuedAt){toast('Expiry date cannot be before issue date.',true);return}(App.state.trainingCertificates||[]).filter(c=>c.staffId===staffId&&c.skillId===skillId&&c.status==='Valid').forEach(c=>{c.status='Superseded';c.supersededAt=P.now()});const c={id:P.uid('CERT'),staffId,skillId,certificateNo:no,issuer:$('#certIssuer').value.trim(),issuedAt,expiresAt,status:'Valid',evidence:ev};App.state.trainingCertificates.push(c);st.trainingCertificates=st.trainingCertificates||[];st.trainingCertificates.push(c.id);st.competencies=st.competencies||[];if(!st.competencies.includes(skillId))st.competencies.push(skillId);P.audit(App.state,'Training certificate issued / renewed','Staff',staffId,'Previous qualification state',skillId,`${no}; evidence ${ev}; expires ${expiresAt}`);await persist();closeModal();render();toast('Competency certificate saved and planning qualification updated.');};
 },0)
}
function newSkillWizard(skillId=null){const existing=skillId?App.state.competencies.find(x=>x.id===skillId):null;App.skillWizard={step:0,existingId:existing?.id||null,data:existing?P.deepClone(existing):{owner:App.state.identity.name,validMonths:24,trainingDurationHours:4,status:'Released'}};renderSkillWizard()}
function captureSkillWizard(){const w=App.skillWizard,d=w.data;if(w.step===0){d.name=$('#nsName').value.trim();d.owner=$('#nsOwner').value.trim();d.description=$('#nsDesc').value.trim()}else if(w.step===1){d.requiredCertificate=$('#nsCert').value.trim();d.validMonths=Number($('#nsMonths').value||24);d.trainingDurationHours=Number($('#nsHours').value||4);d.trainingEvidence=$('#nsEvidence').value.trim()}}
function renderSkillWizard(){const w=App.skillWizard,d=w.data,editing=!!w.existingId,labels=['Define skill','Training rule','Review'];let body='';if(w.step===0)body=`<div class="callout"><h3>1 · ${editing?'Edit':'Define'} the competency</h3><p>${editing?'The competency ID is protected because processes, bookings and certificates reference it. Edit the controlled definition without breaking those links.':'Define what the person must be able to do independently and who owns the qualification standard.'}</p></div><div class="form-grid" style="margin-top:12px">${editing?`<div class="field"><label>Competency ID</label><input value="${esc(w.existingId)}" disabled></div>`:''}<div class="field"><label>Skill name</label><input id="nsName" value="${esc(d.name||'')}"></div><div class="field"><label>Owner</label><input id="nsOwner" value="${esc(d.owner||App.state.identity.name)}"></div><div class="field full"><label>Description / scope</label><textarea id="nsDesc">${esc(d.description||'')}</textarea></div></div>`;else if(w.step===1)body=`<div class="callout"><h3>2 · Define how competence is proven</h3><p>${editing?'Changes apply to future training/renewal planning. Existing issued certificates retain their recorded issue date, expiry and evidence.':'The skill cannot be assigned directly to a person. A training certificate with evidence and expiry is required.'}</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Required certificate type</label><input id="nsCert" value="${esc(d.requiredCertificate||'')}" placeholder="e.g. LASER-JOIN-L2"></div><div class="field"><label>Validity (months)</label><input id="nsMonths" type="number" min="1" value="${esc(d.validMonths||24)}"></div><div class="field"><label>Renewal training duration (hours)</label><input id="nsHours" type="number" min="0.5" step="0.5" value="${esc(d.trainingDurationHours||4)}"></div><div class="field full"><label>Training / evidence requirement</label><textarea id="nsEvidence">${esc(d.trainingEvidence||'')}</textarea></div></div>`;else body=`<div class="callout"><h3>3 · Review controlled skill</h3><p>${editing?'Saving updates the competency master and records the change in the audit trail. Existing certificates remain historical records.':'After creation, issue a person-specific certificate before AUTO-PLAN may use that person for the skill.'}</p></div><div class="grid cols-2" style="margin-top:12px"><div class="card"><span class="subtle">Skill</span><strong>${esc(d.name)}</strong></div><div class="card"><span class="subtle">Owner</span><strong>${esc(d.owner)}</strong></div><div class="card"><span class="subtle">Certificate</span><strong>${esc(d.requiredCertificate)}</strong></div><div class="card"><span class="subtle">Validity</span><strong>${esc(d.validMonths)} months</strong></div><div class="card"><span class="subtle">Renewal duration</span><strong>${esc(d.trainingDurationHours||4)} h</strong></div></div><div class="card" style="margin-top:10px"><strong>Training evidence</strong><p>${esc(d.trainingEvidence)}</p></div>`;openModal(`${editing?'Edit competency':'New skill'} · ${labels[w.step]}`,`<div class="wizard-progress">${labels.map((_,i)=>`<div class="wizard-step ${i<w.step?'done':''} ${i===w.step?'active':''}"></div>`).join('')}</div>${body}`,w.step===0?`${btn('Cancel','data-modal-close','button')}${btn('Next →','data-skill-next','button primary')}`:w.step<labels.length-1?`${btn('Back','data-skill-back','button')}${btn('Next →','data-skill-next','button primary')}`:`${btn('Back','data-skill-back','button')}${btn(editing?'Save competency':'Create controlled skill','data-save-new-skill','button primary')}`,true);setTimeout(()=>{const n=$('[data-skill-next]'),b=$('[data-skill-back]'),save=$('[data-save-new-skill]');if(n)n.onclick=()=>{captureSkillWizard();if(w.step===0&&(!d.name||!d.description)){toast('Define the skill name and scope.',true);return}if(w.step===1&&(!d.requiredCertificate||!d.trainingEvidence)){toast('Define the certificate type and training evidence.',true);return}w.step++;renderSkillWizard()};if(b)b.onclick=()=>{captureSkillWizard();w.step--;renderSkillWizard()};if(save)save.onclick=async()=>{if(editing){const target=App.state.competencies.find(x=>x.id===w.existingId);if(!target){toast('Competency no longer exists.',true);return}const before=P.deepClone(target);Object.assign(target,{name:d.name,description:d.description,owner:d.owner,requiredCertificate:d.requiredCertificate,validMonths:Number(d.validMonths||24),trainingDurationHours:Number(d.trainingDurationHours||4),trainingEvidence:d.trainingEvidence,status:target.status||'Released'});P.audit(App.state,'Competency updated','Competency',target.id,`${before.name} · ${before.validMonths} months`,`${target.name} · ${target.validMonths} months`,App.state.identity.name);await persist();closeModal();render();toast('Competency updated. Existing certificates were preserved.')}else{const id=`COMP-${String(App.state.competencies.length+1).padStart(2,'0')}`;App.state.competencies.push({id,name:d.name,description:d.description,owner:d.owner,requiredCertificate:d.requiredCertificate,validMonths:Number(d.validMonths||24),trainingDurationHours:Number(d.trainingDurationHours||4),trainingEvidence:d.trainingEvidence,status:'Released'});P.audit(App.state,'Competency defined','Competency',id,'—','Released',d.name);await persist();closeModal();render();toast('Skill defined. Issue a training certificate before assigning it to staff.')}}},0)}
function newProcessWizard(){App.processWizard={step:0,data:{owner:App.state.identity.name,basis:'Unit',setupTime:30,cycleTime:15,equipmentCapability:App.state.equipment[0]?.capability||'',competency:App.state.competencies[0]?.id||'',fixedCharge:20,consumableCost:5,workInstruction:['Verify inputs','Execute operation using controlled parameters','Record required evidence']}};renderProcessWizard()}
function captureProcessWizard(){const w=App.processWizard,d=w.data;if(w.step===0){d.name=$('#npName').value.trim();d.family=$('#npFamily').value.trim();d.description=$('#npDesc').value.trim()}else if(w.step===1){d.setupTime=Number($('#npSetup').value||0);d.cycleTime=Number($('#npCycle').value||0);d.basis=$('#npBasis').value;d.equipmentCapability=$('#npEq').value;d.competency=$('#npSkill').value;d.fixedCharge=Number($('#npFixed').value||0);d.consumableCost=Number($('#npConsum').value||0)}else if(w.step===2){d.workInstruction=$('#npWI').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);d.requiredEvidence=$('#npEvidence').value.split(/\n+/).map(x=>x.trim()).filter(Boolean)}}
function renderProcessWizard(){const w=App.processWizard,d=w.data,labels=['Need & scope','Planning standard','Work instruction','Review'];let body='';if(w.step===0)body=`<div class="callout"><h3>1 · Need & scope</h3><p>Define what the new process does and why it is needed. It will remain controlled and unavailable to AUTO-PLAN until released.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Process name</label><input id="npName" value="${esc(d.name||'')}"></div><div class="field"><label>Family</label><input id="npFamily" value="${esc(d.family||'Assembly')}"></div><div class="field full"><label>Purpose / operating scope</label><textarea id="npDesc">${esc(d.description||'')}</textarea></div></div>`;else if(w.step===1)body=`<div class="callout"><h3>2 · Define planning & resource standard</h3><p>This becomes the controlled basis for timing and cost until enough same-product actuals exist to refine the estimate.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Setup time (min)</label><input id="npSetup" type="number" min="0" value="${d.setupTime}"></div><div class="field"><label>Cycle time (min)</label><input id="npCycle" type="number" min="0" value="${d.cycleTime}"></div><div class="field"><label>Basis</label><select id="npBasis"><option ${d.basis==='Unit'?'selected':''}>Unit</option><option ${d.basis==='Batch'?'selected':''}>Batch</option></select></div><div class="field"><label>Equipment capability</label><select id="npEq">${[...new Set(App.state.equipment.map(e=>e.capability))].map(x=>`<option ${d.equipmentCapability===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field full"><label>Required certified skill</label><select id="npSkill">${App.state.competencies.map(c=>`<option value="${c.id}" ${d.competency===c.id?'selected':''}>${esc(c.id)} · ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Fixed process charge (€)</label><input id="npFixed" type="number" min="0" value="${d.fixedCharge}"></div><div class="field"><label>Consumables (€ / ${esc(d.basis)})</label><input id="npConsum" type="number" min="0" value="${d.consumableCost}"></div></div>`;else if(w.step===2)body=`<div class="callout"><h3>3 · Controlled work instruction</h3><p>A released process must contain executable work instructions and required objective evidence.</p></div><div class="field" style="margin-top:12px"><label>Work instruction steps — one per line</label><textarea id="npWI">${esc((d.workInstruction||[]).join('\n'))}</textarea></div><div class="field" style="margin-top:12px"><label>Required evidence — one per line</label><textarea id="npEvidence">${esc((d.requiredEvidence||['Guided build completion','Equipment ID','Operator record']).join('\n'))}</textarea></div>`;else body=`<div class="callout"><h3>4 · Review before controlled release</h3><p>Creation sets the process to <b>Under review</b>. A Process Engineer must release it before it can be used as a standard route operation.</p></div><div class="grid cols-2" style="margin-top:12px"><div class="card"><span class="subtle">Process</span><strong>${esc(d.name)}</strong><p>${esc(d.description)}</p></div><div class="card"><span class="subtle">Planning standard</span><strong>${d.setupTime} min setup + ${d.cycleTime} min/${esc(d.basis)}</strong><p>${esc(d.equipmentCapability)} · ${esc(App.state.competencies.find(c=>c.id===d.competency)?.name||d.competency)}</p></div><div class="card"><span class="subtle">Cost basis</span><strong>${P.currency(d.fixedCharge)} fixed + ${P.currency(d.consumableCost)} consumables</strong></div><div class="card"><span class="subtle">Work instruction</span><strong>${(d.workInstruction||[]).length} controlled steps</strong></div></div>`;openModal(`New process · ${labels[w.step]}`,`<div class="wizard-progress">${labels.map((_,i)=>`<div class="wizard-step ${i<w.step?'done':''} ${i===w.step?'active':''}"></div>`).join('')}</div>${body}`,w.step===0?`${btn('Cancel','data-modal-close','button')}${btn('Next →','data-process-next','button primary')}`:w.step<labels.length-1?`${btn('Back','data-process-back','button')}${btn('Next →','data-process-next','button primary')}`:`${btn('Back','data-process-back','button')}${btn('Create for review','data-save-new-process','button primary')}`,true);setTimeout(()=>{const n=$('[data-process-next]'),b=$('[data-process-back]'),save=$('[data-save-new-process]');if(n)n.onclick=()=>{captureProcessWizard();if(w.step===0&&(!d.name||!d.description)){toast('Define process name and scope.',true);return}if(w.step===1&&(!d.equipmentCapability||!d.competency)){toast('Define equipment capability and required certified skill.',true);return}if(w.step===2&&((d.workInstruction||[]).length<2||(d.requiredEvidence||[]).length<1)){toast('At least two work-instruction steps and one evidence item are required.',true);return}w.step++;renderProcessWizard()};if(b)b.onclick=()=>{captureProcessWizard();w.step--;renderProcessWizard()};if(save)save.onclick=async()=>{const id=`PROC-${String(App.state.processes.length+1).padStart(3,'0')}`;App.state.processes.push({id,name:d.name,family:d.family,revision:'A',status:'Under review',owner:App.state.identity.name,description:d.description,setupTime:d.setupTime,cycleTime:d.cycleTime,basis:d.basis,equipmentCapability:d.equipmentCapability,competency:d.competency,fixedCharge:d.fixedCharge,consumableCost:d.consumableCost,params:[],requiredEvidence:d.requiredEvidence,workInstruction:{id:`WI-${id}`,revision:'A',title:`Work instruction · ${d.name}`,status:'Draft',steps:d.workInstruction},revisionHistory:[{rev:'A',status:'Under review',date:P.todayISO(),note:'Guided process definition'}],approvals:[]});P.audit(App.state,'New process defined','Process',id,'—','Under review','Guided process definition complete');await persist();closeModal();render();toast('Process created Under review. Release only after controlled review.')}} ,0)}
async function releaseLibraryProcess(id){const p=App.state.processes.find(x=>x.id===id);if(!p)return;if(!p.workInstruction?.steps?.length||!p.equipmentCapability||!p.competency||!Number.isFinite(Number(p.setupTime))||!Number.isFinite(Number(p.cycleTime))){toast('Cannot release: work instruction, planning time, equipment capability and certified skill are mandatory.',true);return}p.status='Released';p.workInstruction.status='Released';p.approvals=p.approvals||[];p.approvals.push({role:roleLabel(currentRole()),person:App.state.identity.name,date:P.todayISO()});P.audit(App.state,'Process released','Process',id,'Under review','Released','Controlled definition and work instruction complete');await persist();render();toast('Process released and available for future routes.')}
function editFinanceModal(){const f=App.state.settings.finance;openModal('Finance & costing master data',`<div class="callout"><h3>Controlled costing inputs</h3><p>These rates drive request estimates and management finance KPIs; actual build costs remain separate.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Contingency %</label><input id="finCont" type="number" min="0" value="${f.contingencyPct}"></div>${Object.entries(f.roleRates).map(([r,v])=>`<div class="field"><label>${esc(roleLabel(r))} €/h</label><input data-fin-rate="${r}" type="number" min="0" value="${v}"></div>`).join('')}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save finance rates','data-save-finance','button primary')}`);setTimeout(()=>{$('[data-save-finance]').onclick=async()=>{f.contingencyPct=Number($('#finCont').value||0);$$('[data-fin-rate]').forEach(x=>f.roleRates[x.dataset.finRate]=Number(x.value||0));P.audit(App.state,'Finance master data updated','Settings','finance','Previous rates','Updated',App.state.identity.name);await persist();closeModal();render();toast('Finance rates updated.')}},0)}
