function viewCalibrationCertificates(id){const e=App.state.equipment.find(x=>x.id===id),rows=(App.state.calibrationCertificates||[]).filter(c=>c.equipmentId===id).sort((a,b)=>String(b.completedAt).localeCompare(String(a.completedAt)));const mayAdd=can('calibration:manage')||currentRole()==='administrator';openModal(`Calibration certificates · ${e.name}`,`<div class="callout"><h3>Calibration traceability</h3><p>Each record retains certificate number, issuer, traceability/reference standard, calibration date, next due date, result and evidence reference.</p></div><div style="height:12px"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Certificate</th><th>Issuer</th><th>Completed</th><th>Next due</th><th>Reference / evidence</th><th>Result</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.certificateNo)}</strong>${c.fileName?`<br><small>${esc(c.fileName)}</small>`:''}</td><td>${esc(c.issuer||'—')}</td><td>${P.formatDate(c.completedAt)}</td><td>${P.formatDate(c.nextDue)}</td><td>${esc(c.referenceStandard||'—')}<br><small>${esc(c.evidence||'—')}</small></td><td>${status(c.result||c.status||'Recorded')}</td></tr>`).join('')||'<tr><td colspan="6">No calibration certificate recorded.</td></tr>'}</tbody></table></div>`,`${btn('Close','data-modal-close','button')}${mayAdd?btn('+ Add certificate',`data-modal-add-cal="${id}"`,'button primary'):''}`,true);setTimeout(()=>{const b=$('[data-modal-add-cal]');if(b)b.onclick=()=>addCalibrationCertificateModal(id)},0)}
